import type { GameState, Ship, EntityId, TurretState, Vector3 } from '../../types/index.js';
import { computeInterceptPoint } from '../math/ballisticIntercept.js';
import { DEBUG_AI } from '../../utils/env';
import { pickBestTurretTarget } from './turretTargeting.js';
import {
  findNearestEnemy as sharedFindNearestEnemy,
  findNearbyEnemies as sharedFindNearbyEnemies,
  findNearbyFriends as sharedFindNearbyFriends,
} from '../searchUtils.js';

// Per-frame turret target cache to avoid repeated nearest/radius queries per turret
const turretTargetCache: Map<string, { frame: number; targetId: EntityId | null }> = new Map();
function cacheKey(frame: number, shipId: number, turretId: string) {
  return `${frame}|${shipId}|${turretId}`;
}

export function findNearestEnemy(state: GameState, ship: Ship): Ship | null {
  return sharedFindNearestEnemy(state, ship);
}
export function findNearbyEnemies(state: GameState, ship: Ship, range: number): Ship[] {
  return sharedFindNearbyEnemies(state, ship, range);
}
export function findNearbyFriends(state: GameState, ship: Ship, range: number): Ship[] {
  return sharedFindNearbyFriends(state, ship, range);
}

export function findBestTurretTarget(
  state: GameState,
  ship: Ship,
  turret: TurretState,
): EntityId | null {
  const cfg = state.behaviorConfig!;
  const turretConfig = cfg.turretConfig;
  const sqrt = Math.sqrt;
  if (cfg.globalSettings.useTurretTargetingHelper) {
    // Check per-frame cache first
    const frame = (state as any).frame ?? state.tick;
    const key = cacheKey(frame, ship.id, turret.id);
    const cached = turretTargetCache.get(key);
    if (cached && cached.frame === frame) return cached.targetId ?? null;

    const id = pickBestTurretTarget(state, ship, turret, turretConfig);
    turretTargetCache.set(key, { frame, targetId: id ?? null });
    return id ?? null;
  }
  let best: Ship | null = null;
  let scoreBest = 0;
  for (const target of state.ships) {
    if (target.team === ship.team || target.health <= 0) continue;
    const dx = target.pos.x - ship.pos.x;
    const dy = target.pos.y - ship.pos.y;
    const dz = target.pos.z - ship.pos.z;
    const distSq = dx * dx + dy * dy + dz * dz;
    const minR = turretConfig.minimumFireRange;
    const maxR = turretConfig.maximumFireRange;
    const minRSq = minR * minR;
    const maxRSq = maxR * maxR;
    if (distSq < minRSq || distSq > maxRSq) {
      if (DEBUG_AI) {
        const dtmp = sqrt(distSq);
        console.log(
          `DEBUG_AI: local scoring candidate OUT_OF_RANGE ship=${ship.id} candidate=${target.id} dist=${dtmp.toFixed(2)} rangeMin=${minR} rangeMax=${maxR}`,
        );
      }
      continue;
    }
    const d = sqrt(distSq);
    let score = 1000 / d;
    score += (target.maxHealth - target.health) * 0.1;
    score += target.level.level * 5;
    if (DEBUG_AI)
      console.log(
        `DEBUG_AI: local scoring candidate ship=${ship.id} candidate=${target.id} dist=${d.toFixed(2)} hp=${target.health} level=${target.level?.level ?? target.level} score=${score}`,
      );
    if (score > scoreBest) {
      scoreBest = score;
      best = target;
    }
  }
  if (DEBUG_AI)
    console.log(`DEBUG_AI: local scoring chosen for ship=${ship.id} => ${best?.id ?? 'null'}`);
  return best?.id ?? null;
}

export function updateTurretLeads(state: GameState, ship: Ship) {
  const cfg = state.behaviorConfig!;
  for (const turretState of ship.turrets) {
    if (!turretState.aiState)
      turretState.aiState = {
        targetId: null,
        lastTargetUpdate: state.time,
      } as TurretState['aiState'];
    const rate = state.simConfig?.targetUpdateRate ?? 0.5;
    const now = state.time;
    if (now - (turretState.aiState!.lastTargetUpdate ?? -1e9) < rate) {
      continue; // throttle turret target/lead updates
    }
    turretState.aiState!.lastTargetUpdate = now;
    const targetId = findBestTurretTarget(state, ship, turretState);
    turretState.aiState!.targetId = targetId ?? null;
    // Use globalSettings.maxInterceptLookahead and turretConfig.leadPredictionTime per config
    if (targetId != null) {
      const targetShip = state.ships.find((s) => s.id === targetId && s.health > 0);
      if (targetShip) {
        const projectileSpeed =
          (ship as any).projectileSpeed ?? (cfg.turretConfig as any).projectileSpeed ?? 0;
        const lookahead =
          cfg.globalSettings.maxInterceptLookahead ?? cfg.turretConfig.leadPredictionTime ?? 0.5;
        const intercept =
          projectileSpeed > 0
            ? computeInterceptPoint(
                ship.pos,
                projectileSpeed,
                targetShip.pos,
                targetShip.vel,
                lookahead,
              )
            : null;
        if (intercept) {
          turretState.aiState!.leadTargetPos = intercept as Vector3;
        } else {
          const lt = cfg.turretConfig.leadPredictionTime ?? 0.5;
          turretState.aiState!.leadTargetPos = {
            x: targetShip.pos.x + (targetShip.vel?.x ?? 0) * lt,
            y: targetShip.pos.y + (targetShip.vel?.y ?? 0) * lt,
            z: targetShip.pos.z + (targetShip.vel?.z ?? 0) * lt,
          };
        }
      }
    } else if (turretState.aiState) {
      delete turretState.aiState!.leadTargetPos;
    }
  }
}

import type { GameState, Team } from '../../types/index.js';
import { makeCellNearestResolver, pickKNearestFromCandidates } from '../searchUtils.js';

// Use WeakMap to attach per-state registries without mutating GameState type
const alarmTimesStore: WeakMap<GameState, Map<Team, number>> = new WeakMap();
const scoutsStore: WeakMap<GameState, Map<Team, number | null>> = new WeakMap();

function getAlarmTimes(state: GameState) {
  let m = alarmTimesStore.get(state);
  if (!m) {
    m = new Map<Team, number>([
      ['red', 0],
      ['blue', 0],
    ]);
    alarmTimesStore.set(state, m);
  }
  return m;
}

function getScouts(state: GameState) {
  let m = scoutsStore.get(state);
  if (!m) {
    m = new Map<Team, number | null>([
      ['red', null],
      ['blue', null],
    ]);
    scoutsStore.set(state, m);
  }
  return m;
}

export class TeamSystems {
  private state: GameState;
  constructor(state: GameState) {
    this.state = state;
  }
  get teamAlarmTimes() {
    return getAlarmTimes(this.state);
  }
  get teamScouts() {
    return getScouts(this.state);
  }
}

export function updateTeamAlarms(state: GameState) {
  const config = state.behaviorConfig!;
  if (!(config as any).globalSettings?.enableAlarmSystem) return;
  const alarmTimes = getAlarmTimes(state);
  for (const ship of state.ships) {
    if (ship.health <= 0 || !ship.aiState) continue;
    const timeSinceLastDamage = state.time - (ship.aiState.lastDamageTime || 0);
    if (
      ship.aiState.recentDamage &&
      ship.aiState.recentDamage > 0 &&
      timeSinceLastDamage <= (config as any).globalSettings.alarmSystemWindowSeconds
    ) {
      alarmTimes.set(ship.team, state.time);
    }
  }
}

export function updateScoutAssignments(state: GameState) {
  const config = state.behaviorConfig!;
  if (!(config as any).globalSettings?.enableScoutBehavior) return;
  const scouts = getScouts(state);
  for (const team of ['red', 'blue'] as Team[]) {
    const teamShips = state.ships.filter((s) => s.team === team && s.health > 0);
    if (teamShips.length === 0) continue;
    const current = scouts.get(team);
    const currentShip = current ? teamShips.find((s) => s.id === current) : null;
    if (!currentShip) {
      // Use grouped resolver to find the friendly ship closest to any enemy
      const resolve = makeCellNearestResolver(state, state.simConfig.spatialGrid.cellSize * 3);
      const enemies = state.ships.filter((s) => s.team !== team && s.health > 0);
      let best = teamShips[0];
      if (enemies.length > 0) {
        let bestD = Infinity;
        for (const ship of teamShips) {
          const candidates = resolve ? resolve(ship.pos) : enemies;
          const shortlist =
            candidates && candidates.length > 0
              ? pickKNearestFromCandidates(ship.pos, candidates, 8)
              : enemies;
          for (const e of shortlist) {
            const dx = ship.pos.x - e.pos.x;
            const dy = ship.pos.y - e.pos.y;
            const dz = ship.pos.z - e.pos.z;
            const d = Math.sqrt(dx * dx + dy * dy + dz * dz);
            if (d < bestD) {
              bestD = d;
              best = ship;
            }
          }
        }
      }
      scouts.set(team, best.id);
    }
  }
}

export function isTeamUnderAlarm(state: GameState, team: Team): boolean {
  const config = state.behaviorConfig!;
  const t = getAlarmTimes(state).get(team) || 0;
  const since = state.time - t;
  return !!(
    (config as any).globalSettings?.enableAlarmSystem &&
    since <= (config as any).globalSettings.alarmSystemWindowSeconds
  );
}

export function getTeamScoutId(state: GameState, team: Team): number | null {
  return getScouts(state).get(team) ?? null;
}

// SVG Loader with change detection and caching
// Handles loading SVG files, detecting changes, and rasterizing to ImageBitmap

import type { GameState as _GameState } from '../types/index.js';
import { getFileWatcher } from '../utils/fileWatcher.js';
import * as logger from '../utils/logger.js';
import { RendererConfig } from '../config/rendererConfig.js';

export interface SVGAsset {
  url: string;
  svgText: string;
  lastModified: number;
  imageBitmap?: ImageBitmap;
}

export interface SVGLoadOptions {
  width?: number;
  height?: number;
  teamColor?: string;
  forceReload?: boolean;
  enableWatching?: boolean;
}

export class SVGLoader {
  private worker: Worker | null = null;
  private assets = new Map<string, SVGAsset>();
  private loadingPromises = new Map<string, Promise<SVGAsset>>();
  private watchedFiles = new Set<string>();

  constructor() {
    // If the application explicitly disables SVG subsystem, avoid initializing anything here.
    try {
      if ((RendererConfig as any)?.disableSvgSubsystem) {
        logger.debug('[SVGLoader] SVG subsystem disabled via RendererConfig.disableSvgSubsystem');
        return;
      }
    } catch (_e) {
      void _e;
    }
    // Feature guard: require OffscreenCanvas and createImageBitmap for performant rasterization
    try {
      const hasOffscreen = typeof (globalThis as any).OffscreenCanvas !== 'undefined';
      const hasCIB = typeof (globalThis as any).createImageBitmap === 'function';
      if (!hasOffscreen || !hasCIB) {
        throw new Error(
          'SVG rasterization requires OffscreenCanvas and createImageBitmap. Please use an up-to-date Chrome.',
        );
      }
    } catch (e) {
      // Surface a clear error and rethrow to prevent silent fallback to slow paths
      try {
        logger.error('[SVGLoader] Feature check failed:', e);
      } catch {
        /* ignore */
      }
      throw e;
    }
    // Defer worker initialization until actually needed (lazy) so that
    // consumers that prefer GLTF models won't spawn the SVG raster worker.
    // Worker will be created on first rasterization attempt.
    this.setupFileWatching();
  }

  // Ensure the worker is initialized (lazy). This is synchronous because
  // initWorker performs synchronous setup of event listeners and may set
  // this.worker to null on failure.
  private ensureWorkerInitialized() {
    // If the SVG subsystem is disabled, never initialize the worker
    try {
      if ((RendererConfig as any)?.disableSvgSubsystem) return;
    } catch {
      /* ignore */
    }
    if (this.worker) return;
    try {
      this.initWorker();
    } catch (_e) {
      void _e; /* ignore - initWorker handles its own errors */
    }
  }

  private initWorker() {
    try {
      // Defensive guard: never create a Worker if the SVG subsystem is disabled.
      try {
        if ((RendererConfig as any)?.disableSvgSubsystem) {
          logger.debug(
            '[SVGLoader] initWorker aborting because RendererConfig.disableSvgSubsystem is true',
          );
          this.worker = null;
          return;
        }
      } catch (_e) { void _e; }
      // Enable worker-based SVG rasterization for better performance
      // Resolve worker URL robustly so the app works whether the server
      // serves the repo root (assets under /dist) or serves the dist
      // directory as the site root. Consumers can override with a
      // runtime `window.__ASSET_BASE__` string (e.g. '/dist' or '/').
      try {
        const assetBase =
          (globalThis as unknown as { __ASSET_BASE__?: string }).__ASSET_BASE__ ?? null;
        if (assetBase) {
          // Ensure no trailing slash issues
          const base = assetBase.endsWith('/') ? assetBase.slice(0, -1) : assetBase;
          // If the runtime provides an explicit asset base, fall back to the
          // conventional filename expected on the server. This is an escape
          // hatch for non-bundled deployments where the worker was prebuilt.
          this.worker = new Worker(`${base}/svgRasterWorker.js`, { type: 'module' });
        } else {
          // Use the bundler-friendly worker pattern. When built with Webpack
          // this causes the worker to be emitted as a JS chunk and the URL
          // will point at the emitted worker file (no raw .ts asset will be
          // requested at runtime).

          // @ts-ignore - import.meta.url usage is supported in ESM builds
          this.worker = new Worker(new URL('./svgRasterWorker.ts', import.meta.url), {
            type: 'module',
          });
        }
      } catch (_e) {
        void _e;
        this.worker = null;
      }
      // Single consolidated message handler for both rasterized responses and structured errors
      if (this.worker) {
        try {
          logger.info('[SVGLoader] Worker instance created (lazy init)');
        } catch {
          /* ignore */
        }
        this.worker.addEventListener('message', (ev) => {
          try {
            const data = ev.data;
            // Structured worker-side error reporting
            if (data && data.type === 'worker-error') {
              logger.error('[SVGLoader] Worker reported error:', data.message, data.stack);
              this.worker?.terminate();
              this.worker = null;
              return;
            }

            if (data && data.type === 'worker-messageerror') {
              logger.error('[SVGLoader] Worker messageerror:', data.detail);
              return;
            }

            // Developer checkpoints from worker module evaluation
            if (data && data.type === 'worker-checkpoint') {
              try {
                logger.debug('[SVGLoader] Worker checkpoint:', (data as any).name);
              } catch {
                /* ignore */
              }
              return;
            }

            // Rasterized responses and other messages
            this.handleWorkerMessage(data);
          } catch (_err) {
            void _err;
          }
        });

        this.worker.addEventListener('error', (e) => {
          try {
            // Better logging: include stack if available
            const err =
              e && (e as unknown as { error?: unknown }).error
                ? (e as unknown as { error?: unknown }).error
                : e;
            logger.warn('[SVGLoader] Worker error event, falling back to main thread:', err);
          } catch (_err) {
            void _err;
          }
          this.worker = null;
        });
        logger.debug('[SVGLoader] SVG rasterization worker initialized');
      }
    } catch (_e) {
      void _e;
      logger.debug(
        '[SVGLoader] Worker initialization failed, using main thread SVG rasterization:',
        _e,
      );
      this.worker = null;
    }
  }

  private handleWorkerMessage(data: unknown) {
    // Handle worker responses if needed for advanced caching
    const d = data as { type?: string; assetKey?: string; imageBitmap?: ImageBitmap };
    if (d.type === 'rasterized' && d.assetKey) {
      // Update asset with rasterized bitmap
      const asset = this.assets.get(d.assetKey);
      if (asset && d.imageBitmap) {
        asset.imageBitmap = d.imageBitmap;
      }
    }
  }

  private setupFileWatching() {
    const fileWatcher = getFileWatcher();

    // Set up global change handler
    fileWatcher.watchMultiple([], (filePath, changeType) => {
      this.handleFileChange(filePath, changeType);
    });
  }

  private handleFileChange(filePath: string, changeType: 'modified' | 'deleted' | 'created') {
    logger.debug(`[SVGLoader] File ${changeType}: ${filePath}`);

    if (changeType === 'modified' || changeType === 'deleted') {
      // Invalidate cache for this file
      this.clearCache(filePath);

      // If file was deleted, stop watching it
      if (changeType === 'deleted') {
        this.unwatchFile(filePath);
      }
    }
    // For 'created', we don't need to do anything special here
    // The file will be loaded when requested
  }

  // Load SVG from URL with change detection
  async loadSVG(url: string, options: SVGLoadOptions = {}): Promise<SVGAsset> {
    const { forceReload = false, enableWatching = true } = options;

    // Start watching this file if not already watched
    if (enableWatching && !this.watchedFiles.has(url)) {
      this.watchFile(url);
    }

    // Check if already loading
    const existingPromise = this.loadingPromises.get(url);
    if (existingPromise && !forceReload) {
      return existingPromise;
    }

    // Check cache
    const cached = this.assets.get(url);
    if (cached && !forceReload) {
      // Check if file has changed
      const hasChanged = await this.hasFileChanged(url, cached.lastModified);
      if (!hasChanged) {
        return cached;
      }
    }

    // Start loading
    const loadPromise = this.performLoad(url, options);
    this.loadingPromises.set(url, loadPromise);

    try {
      const asset = await loadPromise;
      this.assets.set(url, asset);
      return asset;
    } finally {
      this.loadingPromises.delete(url);
    }
  }

  private async performLoad(url: string, options: SVGLoadOptions): Promise<SVGAsset> {
    logger.debug(`[SVGLoader] Attempting to load SVG from: ${url}`);

    // Check for inlined SVG assets first (standalone build)
    let svgText: string;
    let lastModified: number;

    const inlineAssets = (globalThis as unknown as { __INLINE_SVG_ASSETS?: Record<string, string> })
      .__INLINE_SVG_ASSETS;
    const standalone = (globalThis as unknown as { __STANDALONE?: boolean }).__STANDALONE;
    if (inlineAssets) {
      // Extract asset name from URL (e.g., "frigate" from "src/config/assets/svg/frigate.svg")
      const assetMatch = url.match(/([^/]+)\.svg$/);
      const assetName = assetMatch ? assetMatch[1] : null;

      if (assetName && inlineAssets[assetName]) {
        logger.debug(`[SVGLoader] Using inlined SVG asset: ${assetName}`);
        svgText = inlineAssets[assetName];
        lastModified = Date.now(); // Use current time for inlined assets
      } else if (standalone) {
        // Standalone build but asset missing from inline map — avoid HEAD
        // fallbacks that trigger network probes; surface a clear error.
        logger.error(`[SVGLoader] Inlined asset missing in standalone build: ${assetName}`);
        throw new Error(`Inlined SVG asset missing: ${assetName}`);
      } else {
        logger.warn(`[SVGLoader] Inlined asset not found for ${assetName}, falling back to fetch`);
        // Fall back to HTTP fetch
        const response = await fetch(url);
        if (!response.ok) {
          logger.error(
            `[SVGLoader] Failed to fetch SVG: ${response.status} ${response.statusText} for ${url}`,
          );
          throw new Error(`Failed to load SVG: ${response.status} ${response.statusText}`);
        }
        svgText = await response.text();
        lastModified = await this.getFileModificationTime(url);
      }
    } else {
      // No inlined assets, use HTTP fetch
      const response = await fetch(url);
      if (!response.ok) {
        logger.error(
          `[SVGLoader] Failed to fetch SVG: ${response.status} ${response.statusText} for ${url}`,
        );
        throw new Error(`Failed to load SVG: ${response.status} ${response.statusText}`);
      }
      svgText = await response.text();
      lastModified = await this.getFileModificationTime(url);
    }

    logger.debug(
      `[SVGLoader] Successfully loaded SVG content for ${url}, length: ${svgText.length}`,
    );

    const asset: SVGAsset = {
      url,
      svgText,
      lastModified,
    };

    // Rasterize if dimensions provided
    if (options.width && options.height) {
      logger.debug('[SVGLoader] Starting rasterization for:', url);
      const imageBitmap = await this.rasterizeSVG(asset, options);
      asset.imageBitmap = imageBitmap;
      logger.debug('[SVGLoader] Rasterization completed for:', url);
    }

    return asset;
  }

  private async rasterizeSVG(asset: SVGAsset, options: SVGLoadOptions): Promise<ImageBitmap> {
    // If the SVG subsystem is disabled, fail-fast to avoid creating workers or rasterizing.
    try {
      if ((RendererConfig as any)?.disableSvgSubsystem) throw new Error('SVG subsystem disabled');
    } catch (_e) {
      throw _e;
    }
    // Lazily initialize worker and prefer worker-based rasterization when available for performance.
    try {
      this.ensureWorkerInitialized();
    } catch {
      /* ignore */
    }
    if (this.worker) {
      try {
        logger.debug('[SVGLoader] Rasterizing SVG using worker:', asset.url);
        const bmp = await this.rasterizeWithWorker(asset, options);
        logger.debug('[SVGLoader] Worker rasterization succeeded:', asset.url);
        return bmp;
      } catch (err) {
        logger.warn('[SVGLoader] Worker rasterization failed, falling back to main thread:', err);
        // fall through to main thread rasterization
      }
    }

    logger.debug('[SVGLoader] Rasterizing SVG with main thread:', asset.url);
    return this.rasterizeMainThread(asset, options);
  }

  private async rasterizeWithWorker(
    asset: SVGAsset,
    options: SVGLoadOptions,
  ): Promise<ImageBitmap> {
    // Respect disableSvgSubsystem flag
    try {
      if ((RendererConfig as any)?.disableSvgSubsystem) throw new Error('SVG subsystem disabled');
    } catch (_e) {
      throw _e;
    }
    // Lazily initialize the worker here so the worker is only created when
    // rasterization is actually needed.
    this.ensureWorkerInitialized();

    return new Promise((resolve, reject) => {
      if (!this.worker) {
        reject(new Error('Worker not available'));
        return;
      }

      const messageHandler = (e: MessageEvent) => {
        const data = e.data;
        // Perf events bubbled from worker
        if (
          data &&
          data.type === 'perf' &&
          (globalThis as any).__perf &&
          typeof (globalThis as any).__perf.addEvent === 'function'
        ) {
          try {
            (globalThis as any).__perf.addEvent({ name: data.name, ms: data.ms });
          } catch {
            /* ignore */
          }
        }
        if (data.type === 'rasterized' && data.assetKey === asset.url) {
          this.worker!.removeEventListener('message', messageHandler);
          resolve(data.imageBitmap);
        }
      };

      this.worker.addEventListener('message', messageHandler);

      // Send rasterization request
      const msg = {
        type: 'rasterize',
        svgText: asset.svgText,
        width: options.width!,
        height: options.height!,
        assetKey: asset.url,
        teamColor: options.teamColor,
        filePath: asset.url,
        fileModTime: asset.lastModified,
      } as const;
      try {
        // Message-size audit for raster requests (approximate, JSON-based)
        if (
          (globalThis as any).__perf &&
          typeof (globalThis as any).__perf.addEvent === 'function'
        ) {
          const approxKB = JSON.stringify(msg).length / 1000;
          (globalThis as any).__perf.addEvent({ name: 'raster.request.sendKB', ms: approxKB });
        }
      } catch {
        /* ignore */
      }
      this.worker.postMessage(msg);

      // Timeout after 8 seconds (increased timeout)
      setTimeout(() => {
        this.worker!.removeEventListener('message', messageHandler);
        reject(new Error('Rasterization timeout'));
      }, 8000);
    });
  }

  private async rasterizeMainThread(
    asset: SVGAsset,
    options: SVGLoadOptions,
  ): Promise<ImageBitmap> {
    // Use regular Canvas instead of OffscreenCanvas for better SVG compatibility
    const canvas = document.createElement('canvas');
    canvas.width = options.width!;
    canvas.height = options.height!;
    // Request a 2D context optimized for frequent readbacks (tinting, getImageData).
    const ctx =
      (canvas.getContext('2d', {
        willReadFrequently: true,
      } as unknown) as CanvasRenderingContext2D) || canvas.getContext('2d')!;

    // Clear canvas
    ctx.clearRect(0, 0, options.width!, options.height!);

    try {
      logger.debug('[SVGLoader] Attempting to rasterize SVG in main thread for:', asset.url);

      // Create a properly formatted SVG data URL
      let svgContent = asset.svgText;

      // Ensure SVG has proper dimensions if missing
      if (!svgContent.includes('width=') || !svgContent.includes('height=')) {
        svgContent = svgContent.replace(
          /<svg([^>]*)>/,
          `<svg$1 width="${options.width}" height="${options.height}">`,
        );
      }

      // Create data URL with proper encoding
      const svgDataUrl = `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(svgContent)))}`;

      // Load SVG as image
      const img = new Image();
      img.crossOrigin = 'anonymous';

      await new Promise<void>((resolve, reject) => {
        const timeoutId = setTimeout(() => {
          reject(new Error('SVG image load timeout after 10 seconds'));
        }, 10000);

        img.onload = () => {
          clearTimeout(timeoutId);
          logger.debug('[SVGLoader] Successfully loaded SVG image:', asset.url);
          resolve();
        };

        img.onerror = (e) => {
          clearTimeout(timeoutId);
          logger.error('[SVGLoader] Failed to load SVG image:', e);
          reject(new Error(`SVG image load failed`));
        };

        img.src = svgDataUrl;
      });

      // Draw the SVG image to canvas with proper scaling
      ctx.save();
      ctx.clearRect(0, 0, options.width!, options.height!);

      // Scale image to fit canvas
      const scale = Math.min(options.width! / img.width, options.height! / img.height);
      const scaledWidth = img.width * scale;
      const scaledHeight = img.height * scale;
      const offsetX = (options.width! - scaledWidth) / 2;
      const offsetY = (options.height! - scaledHeight) / 2;

      ctx.drawImage(img, offsetX, offsetY, scaledWidth, scaledHeight);
      ctx.restore();

      // Apply team color tinting if specified
      if (options.teamColor) {
        // When applying tinting we do pixel reads; request willReadFrequently where supported.
        const ctx =
          (canvas.getContext('2d', {
            willReadFrequently: true,
          } as unknown) as CanvasRenderingContext2D) || canvas.getContext('2d')!;
        this.applyTeamColorTint(ctx, options.width!, options.height!, options.teamColor);
      }

      logger.debug('[SVGLoader] Successfully rasterized SVG to canvas:', asset.url);

      // Convert canvas to ImageBitmap
      return await createImageBitmap(canvas);
    } catch (_error) {
      void _error;
      logger.error('[SVGLoader] SVG rasterization failed completely:', _error);

      // Return error - don't create geometric fallback here anymore
      // Let the renderer handle fallbacks appropriately
      const errorMessage = _error instanceof Error ? _error.message : String(_error);
      throw new Error(`Failed to rasterize SVG ${asset.url}: ${errorMessage}`);
    }
  }

  // Apply team color tinting to the rasterized SVG
  private applyTeamColorTint(
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    teamColor: string,
  ) {
    // Avoid expensive pixel readbacks by using 2D compositing operations.
    // Draw a solid rectangle filled with the team color using a compositing
    // mode that restricts the color fill to the existing non-transparent
    // pixels of the canvas. 'source-atop' will draw the fill only where
    // destination pixels exist, preserving alpha. This avoids getImageData.
    try {
      ctx.save();
      ctx.globalCompositeOperation = 'source-atop';
      ctx.fillStyle = teamColor;
      ctx.fillRect(0, 0, width, height);
    } finally {
      ctx.restore();
    }
  }

  // Check if file has changed since last load
  private async hasFileChanged(url: string, lastModified: number): Promise<boolean> {
    try {
      const currentModTime = await this.getFileModificationTime(url);
      return currentModTime > lastModified;
    } catch {
      // If we can't check modification time, assume no change
      return false;
    }
  }

  // Get file modification time
  // Note: In browser environment, we use a combination of approaches
  private async getFileModificationTime(url: string): Promise<number> {
    try {
      // If asset is inlined in the standalone HTML, avoid HEAD requests
      try {
        const inlineAssets = (
          globalThis as unknown as { __INLINE_SVG_ASSETS?: Record<string, string> }
        ).__INLINE_SVG_ASSETS;
        if (inlineAssets && typeof url === 'string' && url.endsWith('.svg')) {
          const m = url.match(/([^/]+)\.svg$/);
          const name = m ? m[1] : null;
          if (name && inlineAssets[name]) {
            // Use a stable surrogate mod-time for inlined assets
            return Date.now();
          }
        }
      } catch (_e) {
        void _e;
      }

      // Try to get from response headers
      // If running as a standalone inlined build, avoid issuing HEAD requests
      // for SVG assets because they are embedded. This prevents browsers from
      // creating transient HEAD requests that can be aborted and logged.
      try {
        const standalone = (globalThis as unknown as { __STANDALONE?: boolean }).__STANDALONE;
        if (standalone && typeof url === 'string' && url.endsWith('.svg')) {
          return Date.now();
        }
      } catch (_e) {
        void _e;
      }

      const response = await fetch(url, {
        method: 'HEAD',
        cache: 'no-cache',
      });
      const lastModified = response.headers.get('last-modified');
      if (lastModified) {
        return new Date(lastModified).getTime();
      }
    } catch {
      // Ignore errors
    }

    // Fallback: use current time as modification time
    // In a real implementation, you might want to implement a more sophisticated
    // change detection mechanism, perhaps with ETags or content hashing
    return Date.now();
  }

  // Watch a specific file
  private watchFile(url: string): void {
    if (this.watchedFiles.has(url)) return;

    const fileWatcher = getFileWatcher();
    fileWatcher.watch(url, (filePath, changeType) => {
      this.handleFileChange(filePath, changeType);
    });

    this.watchedFiles.add(url);
  }

  // Stop watching a specific file
  private unwatchFile(url: string): void {
    if (!this.watchedFiles.has(url)) return;

    const fileWatcher = getFileWatcher();
    fileWatcher.unwatch(url);
    this.watchedFiles.delete(url);
  }

  // Clear cache for specific asset or all assets
  clearCache(assetUrl?: string) {
    if (assetUrl) {
      const asset = this.assets.get(assetUrl);
      if (asset && asset.imageBitmap) {
        asset.imageBitmap.close();
      }
      this.assets.delete(assetUrl);
    } else {
      // Clear all
      for (const asset of this.assets.values()) {
        if (asset.imageBitmap) {
          asset.imageBitmap.close();
        }
      }
      this.assets.clear();
    }

    // Notify worker to clear cache
    if (this.worker) {
      this.worker.postMessage({
        type: 'clear-cache',
      });
    }
  }

  // Force reload of all assets
  async reloadAllAssets(): Promise<void> {
    const urls = Array.from(this.assets.keys());
    await Promise.all(urls.map((url) => this.loadSVG(url, { forceReload: true })));
  }

  // Get asset without loading
  getAsset(url: string): SVGAsset | undefined {
    return this.assets.get(url);
  }

  // Check if asset is cached
  hasAsset(url: string): boolean {
    return this.assets.has(url);
  }

  // Get cache statistics
  getCacheStats() {
    return {
      cachedAssets: this.assets.size,
      loadingPromises: this.loadingPromises.size,
      watchedFiles: this.watchedFiles.size,
    };
  }

  // Cleanup resources
  dispose() {
    if (this.worker) {
      this.worker.terminate();
      this.worker = null;
    }

    // Stop watching all files
    const fileWatcher = getFileWatcher();
    this.watchedFiles.forEach((url) => {
      fileWatcher.unwatch(url);
    });
    this.watchedFiles.clear();

    this.clearCache();
    this.loadingPromises.clear();
  }
}

// Global SVG loader instance
