import type {
  GameState,
  Ship,
  ShipClass,
  Team,
  Vector3,
  EntityId,
  TurretState,
} from '../../types/index.js';
import type { PhysicsAdapter } from '../adapters/physicsAdapter.js';
import type { RendererAdapter } from '../adapters/rendererAdapter.js';
import type { SpatialIndex } from '../spatialIndex.js';
import { getShipClassConfig } from '../../config/entitiesConfig.js';
import * as logger from '../../utils/logger.js';
import { nextLevelXp, applyLevelUps } from '../../config/progression.js';
import { FleetConfig } from '../../config/fleetConfig.js';
import { CarrierSpawnConfig } from '../../config/carrierSpawnConfig.js';

/**
 * Spawn intent describes a request to create an entity
 */
export interface SpawnIntent {
  type: 'ship' | 'bullet' | 'effect';
  team: Team;
  class?: ShipClass;
  position?: Vector3;
  parentId?: EntityId;
  // Additional spawn properties
  initialVelocity?: Vector3;
  initialOrientation?: { pitch: number; yaw: number; roll: number };
  customConfig?: Record<string, any>;
}

/**
 * Spawn result containing the created entity and any side effects
 */
export interface SpawnResult {
  entityId: EntityId;
  success: boolean;
  error?: string;
  spawnedEntity?: Ship; // For ship spawns
}

/**
 * Spawn event for notifications
 */
export interface SpawnEvent {
  type: 'spawned' | 'failed';
  intent: SpawnIntent;
  result: SpawnResult;
  timestamp: number;
}

/**
 * SpawnSystem centralizes entity creation/destruction with proper
 * lifecycle management and adapter coordination.
 */
export class SpawnSystem {
  private state: GameState;
  private physicsAdapter?: PhysicsAdapter;
  private rendererAdapter?: RendererAdapter;
  private spatialIndex?: SpatialIndex;
  // Optional instrumentation toggle for debugging/perf investigation
  private instrumentationEnabled = false;
  // Cache for renderer-related parameter objects (keyed by program-like objects)
  // We don't assume a specific shape — callers must pass the canonical object used by the renderer.
  private rendererParametersCache = new WeakMap<object, unknown>();
  private eventHandlers: ((event: SpawnEvent) => void)[] = [];

  constructor(
    state: GameState,
    adapters?: {
      physics?: PhysicsAdapter;
      renderer?: RendererAdapter;
      spatial?: SpatialIndex;
    },
  ) {
    this.state = state;
    this.physicsAdapter = adapters?.physics;
    this.rendererAdapter = adapters?.renderer;
    this.spatialIndex = adapters?.spatial;
  }

  /**
   * Subscribe to spawn events
   */
  onSpawnEvent(handler: (event: SpawnEvent) => void): () => void {
    this.eventHandlers.push(handler);
    return () => {
      const index = this.eventHandlers.indexOf(handler);
      if (index >= 0) {
        this.eventHandlers.splice(index, 1);
      }
    };
  }

  private emitEvent(event: SpawnEvent): void {
    for (const handler of this.eventHandlers) {
      try {
        handler(event);
      } catch (_error) {
        void _error;
        logger.warn('Error in spawn event handler:', _error);
      }
    }
  }

  /**
   * Spawn a ship with proper initialization
   */
  spawnShip(intent: SpawnIntent): SpawnResult {
    if (intent.type !== 'ship' || !intent.class) {
      const result: SpawnResult = {
        entityId: -1,
        success: false,
        error: 'Invalid ship spawn intent',
      };
      this.emitEvent({
        type: 'failed',
        intent,
        result,
        timestamp: this.state.time,
      });
      return result;
    }

    try {
      const ship = this.createShip(intent);
      const result: SpawnResult = {
        entityId: ship.id,
        success: true,
        spawnedEntity: ship,
      };

      // Register with adapters
      this.registerShipWithAdapters(ship);

      this.emitEvent({
        type: 'spawned',
        intent,
        result,
        timestamp: this.state.time,
      });

      return result;
    } catch (_error) {
      void _error;
      const result: SpawnResult = {
        entityId: -1,
        success: false,
        error: _error instanceof Error ? _error.message : 'Unknown spawn error',
      };
      this.emitEvent({
        type: 'failed',
        intent,
        result,
        timestamp: this.state.time,
      });
      return result;
    }
  }

  /**
   * Spawn multiple ships (fleet spawning)
   */
  spawnFleet(
    team: Team,
    count: number = 5,
    options?: {
      classes?: ShipClass[];
      formation?: 'random' | 'line' | 'wedge';
    },
  ): SpawnResult[] {
    const results: SpawnResult[] = [];

    for (let i = 0; i < count; i++) {
      const cls = options?.classes
        ? this.state.rng.pick(options.classes)
        : this.state.rng.pick(['fighter', 'corvette', 'frigate', 'destroyer', 'carrier'] as const);

      const position =
        options?.formation === 'line'
          ? this.calculateFormationPosition(team, i, count, 'line')
          : options?.formation === 'wedge'
            ? this.calculateFormationPosition(team, i, count, 'wedge')
            : undefined; // Random position

      const intent: SpawnIntent = {
        type: 'ship',
        team,
        class: cls,
        position,
      };

      results.push(this.spawnShip(intent));
    }

    return results;
  }

  /**
   * Remove ship and clean up adapters
   */
  removeShip(shipId: EntityId): boolean {
    const shipIndex = this.state.ships.findIndex((s) => s.id === shipId);
    if (shipIndex === -1) {
      return false;
    }
    const ship = this.state.ships[shipIndex];

    // Attempt to invalidate any renderer-side cached parameters for this ship's program-like object
    try {
      const programLike = (ship as unknown as Record<string, unknown>).__renderProgram as
        | object
        | undefined;
      if (programLike) {
        // Ask adapter to invalidate its internal cache if it supports it
        try {
          const maybeAdapter = this.rendererAdapter as unknown as
            | { invalidateParameters?: (p: object) => void }
            | undefined;
          if (maybeAdapter && typeof maybeAdapter.invalidateParameters === 'function') {
            maybeAdapter.invalidateParameters(programLike);
          }
        } catch {
          // ignore adapter failure
        }

        // Remove from local WeakMap cache too (best-effort)
        try {
          this.rendererParametersCache.delete(programLike);
        } catch {
          // ignore
        }
      }
    } catch {
      // ignore
    }

    // Remove from adapters
    this.rendererAdapter?.removeShip(shipId);
    this.physicsAdapter?.removeBody(shipId);
    this.spatialIndex?.remove(shipId);

    // Remove from state
    this.state.ships.splice(shipIndex, 1);
    this.state.shipIndex?.delete(shipId);

    return true;
  }

  /**
   * Get spawn statistics
   */
  getStats(): {
    totalShips: number;
    shipsByTeam: Record<Team, number>;
    shipsByClass: Record<ShipClass, number>;
    nextId: number;
  } {
    const shipsByTeam = { red: 0, blue: 0 } as Record<Team, number>;
    const shipsByClass = {
      fighter: 0,
      corvette: 0,
      frigate: 0,
      destroyer: 0,
      carrier: 0,
    } as Record<ShipClass, number>;

    for (const ship of this.state.ships) {
      shipsByTeam[ship.team]++;
      shipsByClass[ship.class]++;
    }

    return {
      totalShips: this.state.ships.length,
      shipsByTeam,
      shipsByClass,
      nextId: this.state.nextId,
    };
  }

  private createShip(intent: SpawnIntent): Ship {
    const cfg = getShipClassConfig(intent.class!);
    const id = this.allocateId();
    const level = { level: 1, xp: 0, nextLevelXp: nextLevelXp(1) };
    const maxHealth = Math.floor(applyLevelUps(level.level, cfg.baseHealth));
    const maxShield = Math.floor(applyLevelUps(level.level, cfg.shield));
    const turrets: TurretState[] = cfg.turrets.map((t, i) => ({
      id: `${t.id}-${i}`,
      cooldownLeft: 0,
    }));

    const pos = intent.position ?? this.randomSpawnPos(intent.team);
    const randomYaw = this.state.rng.next() * Math.PI * 2;

    const ship: Ship = {
      id,
      team: intent.team,
      class: intent.class!,
      pos: { x: pos.x, y: pos.y, z: pos.z },
      vel: intent.initialVelocity ?? { x: 0, y: 0, z: 0 },
      orientation: intent.initialOrientation ?? {
        pitch: 0,
        yaw: randomYaw,
        roll: 0,
      },
      dir: randomYaw, // Legacy compatibility
      targetId: null,
      health: maxHealth,
      maxHealth,
      armor: cfg.armor,
      shield: maxShield,
      maxShield,
      shieldRegen: cfg.shieldRegen,
      speed: cfg.speed,
      turnRate: cfg.turnRate,
      turrets,
      kills: 0,
      level,
      spawnedFighters: intent.class === 'carrier' ? 0 : undefined,
      fighterSpawnCdLeft:
        intent.class === 'carrier' ? CarrierSpawnConfig.fighter.initialCooldown : undefined,
      parentCarrierId: intent.parentId,
    };

    // Apply spawn jitter if enabled
    this.applySpawnJitter(ship);

    // Add to state
    this.state.ships.push(ship);
    this.state.shipIndex?.set(ship.id, ship);

    return ship;
  }

  private applySpawnJitter(ship: Ship): void {
    const enableJitter = this.state.behaviorConfig?.globalSettings.enableSpawnJitter;
    if (enableJitter) {
      const jitterScale = 0.02; // fraction of ship.speed per second
      const angle = this.state.rng.next() * Math.PI * 2;
      const jitterMag = ship.speed * jitterScale;
      ship.vel.x += Math.cos(angle) * jitterMag;
      ship.vel.y += Math.sin(angle) * jitterMag;
    }
  }

  private randomSpawnPos(team: Team): Vector3 {
    const margin = FleetConfig.spawning.margin;
    const y = this.state.rng.int(margin, this.state.simConfig.simBounds.height - margin);
    const z = this.state.rng.int(margin, this.state.simConfig.simBounds.depth - margin);
    const x =
      team === 'red'
        ? this.state.rng.int(margin, margin + FleetConfig.spawning.spawnWidth)
        : this.state.rng.int(
            this.state.simConfig.simBounds.width - margin - FleetConfig.spawning.spawnWidth,
            this.state.simConfig.simBounds.width - margin,
          );
    return { x, y, z };
  }

  private calculateFormationPosition(
    team: Team,
    index: number,
    total: number,
    formation: 'line' | 'wedge',
  ): Vector3 {
    const basePos = this.randomSpawnPos(team);
    const spacing = 50; // Distance between ships in formation

    switch (formation) {
      case 'line': {
        const offset = (index - total / 2) * spacing;
        return {
          x: basePos.x,
          y: basePos.y + offset,
          z: basePos.z,
        };
      }
      case 'wedge': {
        const row = Math.floor(Math.sqrt(index * 2));
        const posInRow = index - (row * (row + 1)) / 2;
        const rowWidth = (row + 1) * spacing;
        const yOffset = posInRow * spacing - rowWidth / 2;
        const xOffset = row * spacing * 0.5;

        return {
          x: basePos.x + (team === 'red' ? xOffset : -xOffset),
          y: basePos.y + yOffset,
          z: basePos.z,
        };
      }
      default:
        return basePos;
    }
  }

  private registerShipWithAdapters(ship: Ship): void {
    // Register with physics
    try {
      if (this.physicsAdapter) {
        const cfg = getShipClassConfig(ship.class);
        this.physicsAdapter.addBody(ship.id, {
          position: ship.pos,
          velocity: ship.vel,
          mass: cfg.baseHealth, // Use health as mass approximation
          radius: 20, // Default ship radius
          collisionMask: ship.team === 'red' ? 0x01 : 0x02,
        });
      }
    } catch (_error) {
      void _error;
      logger.warn('Failed to register ship with physics adapter:', _error);
    }

    // Register with renderer
    try {
      if (this.rendererAdapter) {
        if (this.instrumentationEnabled) {
          try {
            logger.debug('renderer.ensureMeshForShip');
          } catch (_e) {
            void _e;
            void _e;
          }
        }

        // If the renderer adapter exposes a program/parameter object on the ship (conventionally
        // some adapters attach a reference after first creation) we try to avoid repeated expensive
        // parameter computation by caching results keyed by that object. This is a no-op for adapters
        // that don't follow that convention.
        // Usage: adapter implementations may choose to attach `__renderProgram` or similar to ship
        // after the first call. This helper is intentionally conservative and will not mutate ship.
        const programLike = (ship as unknown as Record<string, unknown>).__renderProgram as
          | object
          | undefined;
        if (programLike && typeof this.rendererParametersCache.get === 'function') {
          // If we already have cached parameters for this program-like object, we could use it.
          // We don't change adapter behavior here, but this cache can be read by future helpers
          // or instrumented code paths to avoid repeating heavy work.
          if (!this.rendererParametersCache.has(programLike)) {
            try {
              // If adapter exposes a `getParameters` method we call it once and cache the result.
              const maybeAdapter = this.rendererAdapter as unknown as
                | { getParameters?: (p: object) => unknown }
                | undefined;
              if (maybeAdapter && typeof maybeAdapter.getParameters === 'function') {
                const params = maybeAdapter.getParameters(programLike);
                this.rendererParametersCache.set(programLike, params);
              }
            } catch {
              // Swallow: this is best-effort instrumentation/caching
            }
          }
        }

        this.rendererAdapter.ensureMeshForShip(ship);
      }
    } catch (_error) {
      void _error;
      logger.warn('Failed to register ship with renderer adapter:', _error);
    }

    // Register with spatial index
    try {
      if (this.spatialIndex) {
        this.spatialIndex.insert(ship.id, ship.pos, 20, ship.team);
      }
    } catch (_error) {
      void _error;
      logger.warn('Failed to register ship with spatial index:', _error);
    }
  }

  private allocateId(): EntityId {
    return this.state.nextId++;
  }
}

import * as THREE from 'three';
import type { Bullet } from '../types/index.js';
import { RendererConfig } from '../config/rendererConfig.js';
import * as logger from '../utils/logger.js';

/**
 * BulletInstancer manages bullet rendering using THREE.InstancedMesh for improved performance
 * when there are many bullets. This replaces individual Mesh objects with a single instanced mesh.
 */
export class BulletInstancer {
  private instancedMesh: THREE.InstancedMesh;
  private capacity: number;
  private activeBullets = new Map<number, number>(); // bulletId -> instanceIndex
  private freeIndices: number[] = [];
  private usedCount = 0;
  private hasWarned = false;
  // Readiness signalling: set to true once the instanced mesh is created and added to the scene
  public isReady = false;
  private readyCallbacks: Array<() => void> = [];

  // Temporary objects for matrix calculations to avoid allocations
  private tempMatrix = new THREE.Matrix4();
  private tempPosition = new THREE.Vector3();
  private tempScale = new THREE.Vector3(1, 1, 1);
  private tempQuaternion = new THREE.Quaternion();

  constructor(scene: THREE.Scene, bulletsGroup: THREE.Group) {
    this.capacity = RendererConfig.instancing.bullets.initialCapacity;

    // Create shared geometry and material for all bullet instances
    const geometry = new THREE.SphereGeometry(2.2, 8, 8);
    const material = new THREE.MeshBasicMaterial({ color: 0xffdd88 });

    // Create the instanced mesh
    this.instancedMesh = new THREE.InstancedMesh(geometry, material, this.capacity);
    // InstancedMesh frustum culling doesn't account for per-instance transforms.
    // Disable frustum culling so instances aren't incorrectly culled when their
    // transforms move them outside the original geometry bounding sphere.
    this.instancedMesh.frustumCulled = false;

    // Initialize free indices pool
    for (let i = 0; i < this.capacity; i++) {
      this.freeIndices.push(i);
    }

    // Hide unused instances by setting them to zero scale
    this.hideUnusedInstances();
    // Ensure the GPU sees the initial matrices we wrote during hideUnusedInstances
    this.instancedMesh.instanceMatrix.needsUpdate = true;

    // Add to scene
    bulletsGroup.add(this.instancedMesh);

    // Mark as ready and notify any listeners
    this.isReady = true;
    for (const cb of this.readyCallbacks) {
      try {
        cb();
      } catch (_e) {
        void _e;
        logger.error('Error in BulletInstancer readiness callback', _e);
      }
    }
    this.readyCallbacks.length = 0;

    logger.info(`BulletInstancer initialized with capacity ${this.capacity}`);
  }

  /**
   * Register a callback to be invoked when the instancer is ready.
   * If the instancer is already ready the callback is invoked immediately.
   */
  onReady(cb: () => void): void {
    if (this.isReady) {
      try {
        cb();
      } catch (_e) {
        void _e;
        logger.error('Error in BulletInstancer readiness callback', _e);
      }
      return;
    }
    this.readyCallbacks.push(cb);
  }

  /**
   * Allocate an instance for a new bullet
   */
  allocateInstance(bulletId: number): boolean {
    // Check if bullet already has an instance
    if (this.activeBullets.has(bulletId)) {
      logger.warn(`Bullet ${bulletId} already has an allocated instance`);
      return true;
    }

    // Check if we need to grow capacity
    if (this.freeIndices.length === 0) {
      if (!this.growCapacity()) {
        return false;
      }
    }

    // Allocate from free indices
    const instanceIndex = this.freeIndices.pop()!;
    this.activeBullets.set(bulletId, instanceIndex);
    this.usedCount++;

    // Check if we should warn about capacity usage
    const usage = this.usedCount / this.capacity;
    if (!this.hasWarned && usage > RendererConfig.instancing.bullets.warnThreshold) {
      logger.warn(
        `Bullet instancer usage high: ${Math.round(usage * 100)}% (${this.usedCount}/${this.capacity})`,
      );
      this.hasWarned = true;
    }

    return true;
  }

  /**
   * Free an instance for a removed bullet
   */
  freeInstance(bulletId: number): boolean {
    const instanceIndex = this.activeBullets.get(bulletId);
    if (instanceIndex === undefined) {
      return false;
    }

    // Hide the instance by setting scale to zero
    this.tempMatrix.makeScale(0, 0, 0);
    this.instancedMesh.setMatrixAt(instanceIndex, this.tempMatrix);

    // Return to free pool
    this.freeIndices.push(instanceIndex);
    this.activeBullets.delete(bulletId);
    this.usedCount--;

    // Reset warning flag if usage is low again
    if (
      this.hasWarned &&
      this.usedCount / this.capacity < RendererConfig.instancing.bullets.warnThreshold * 0.8
    ) {
      this.hasWarned = false;
    }

    return true;
  }

  /**
   * Update bullet transform
   */
  updateBulletTransform(bullet: Bullet, interpolatedPos?: THREE.Vector3): boolean {
    const instanceIndex = this.activeBullets.get(bullet.id);
    if (instanceIndex === undefined) {
      return false;
    }
    // Defensive: derive an interpolated position if not provided. Many tests
    // construct bullets with only `pos` and omit `prevPos`; default to `pos`
    // to avoid runtime errors during rendering tests.
    const pAny: any =
      interpolatedPos ?? new THREE.Vector3(bullet.pos.x, bullet.pos.y, bullet.pos.z);
    // Ensure numeric x/y/z are present — test mocks for THREE.Vector3 may not set them.
    if (!Number.isFinite(pAny.x) || !Number.isFinite(pAny.y) || !Number.isFinite(pAny.z)) {
      if (
        bullet.pos &&
        Number.isFinite(bullet.pos.x) &&
        Number.isFinite(bullet.pos.y) &&
        Number.isFinite(bullet.pos.z)
      ) {
        pAny.x = bullet.pos.x;
        pAny.y = bullet.pos.y;
        pAny.z = bullet.pos.z;
      }
    }
    if (!pAny || !Number.isFinite(pAny.x) || !Number.isFinite(pAny.y) || !Number.isFinite(pAny.z)) {
      try {
        logger.error('[INSTANCER_ERROR][BulletInstancer] non-finite bullet pos', {
          bulletId: bullet.id,
          pos: pAny,
        });
      } catch (_e) {
        void _e;
      }
      return false;
    }

    // Set position and identity rotation/scale
    // tempPosition.copy expects a THREE.Vector3-like object; our pAny may be a plain object, but copy mock accepts it in tests.
    this.tempPosition.copy(pAny as any);
    this.tempMatrix.compose(this.tempPosition, this.tempQuaternion, this.tempScale);
    this.instancedMesh.setMatrixAt(instanceIndex, this.tempMatrix);

    return true;
  }

  /**
   * Call this once per frame after all updates
   */
  markMatrixNeedsUpdate(): void {
    this.instancedMesh.instanceMatrix.needsUpdate = true;
  }

  /**
   * Check if a bullet has an allocated instance
   */
  hasBullet(bulletId: number): boolean {
    return this.activeBullets.has(bulletId);
  }

  /**
   * Get all active bullet IDs
   */
  getActiveBulletIds(): number[] {
    return Array.from(this.activeBullets.keys());
  }

  /**
   * Get current usage statistics
   */
  getStats() {
    return {
      capacity: this.capacity,
      used: this.usedCount,
      free: this.freeIndices.length,
      usagePercent: Math.round((this.usedCount / this.capacity) * 100),
    };
  }

  /**
   * Dispose resources
   */
  dispose(): void {
    this.instancedMesh.geometry.dispose();
    if (Array.isArray(this.instancedMesh.material)) {
      this.instancedMesh.material.forEach((mat) => mat.dispose());
    } else {
      this.instancedMesh.material.dispose();
    }
    this.activeBullets.clear();
    this.freeIndices.length = 0;
    logger.info('BulletInstancer disposed');
  }

  /**
   * Grow the capacity of the instanced mesh
   */
  private growCapacity(): boolean {
    const newCapacity = Math.min(
      Math.ceil(this.capacity * RendererConfig.instancing.bullets.growthFactor),
      RendererConfig.instancing.bullets.maxCapacity,
    );

    if (newCapacity <= this.capacity) {
      logger.error(
        `Cannot grow bullet instancer capacity beyond ${this.capacity} (max: ${RendererConfig.instancing.bullets.maxCapacity})`,
      );
      return false;
    }

    logger.info(`Growing bullet instancer capacity from ${this.capacity} to ${newCapacity}`);

    // Create new instanced mesh with larger capacity
    const oldInstancedMesh = this.instancedMesh;
    const geometry = oldInstancedMesh.geometry;
    const material = oldInstancedMesh.material;

    this.instancedMesh = new THREE.InstancedMesh(geometry, material, newCapacity);
    // Same reason as above: disable frustum culling for the new instanced mesh
    this.instancedMesh.frustumCulled = false;

    // Copy existing matrices
    for (let i = 0; i < this.capacity; i++) {
      oldInstancedMesh.getMatrixAt(i, this.tempMatrix);
      this.instancedMesh.setMatrixAt(i, this.tempMatrix);
    }

    // Add new free indices
    for (let i = this.capacity; i < newCapacity; i++) {
      this.freeIndices.push(i);
    }

    // Hide new unused instances
    this.hideUnusedInstances(this.capacity);

    // Replace in scene
    const parent = oldInstancedMesh.parent;
    if (parent) {
      parent.remove(oldInstancedMesh);
      parent.add(this.instancedMesh);
    }

    this.capacity = newCapacity;
    this.instancedMesh.instanceMatrix.needsUpdate = true;

    return true;
  }

  /**
   * Hide unused instances by setting them to zero scale
   */
  private hideUnusedInstances(startIndex = 0): void {
    this.tempMatrix.makeScale(0, 0, 0);
    for (let i = startIndex; i < this.capacity; i++) {
      this.instancedMesh.setMatrixAt(i, this.tempMatrix);
    }
  }
}

import * as THREE from 'three';
import type { GameState, Ship, Bullet, ShipClass } from '../types/index.js';
import { RendererConfig } from '../config/rendererConfig.js';
import { ShipVisualConfig } from '../config/shipVisualConfig.js';
import { loadSVGAsset } from '../core/svgLoader.js';
import { defaultSVGConfig, getShipSVGUrl } from '../config/svgConfig.js';
import * as logger from '../utils/logger.js';
import { shipInstancer } from './shipInstancer.js';

/**
 * Mesh factory and pooling for ships, bullets, and UI elements
 * Extracted from threeRenderer.ts for SRP compliance
 */

export interface MeshFactoryState {
  billboardMaterials: Set<THREE.ShaderMaterial>;
  billboardMaterialPool: Map<string, THREE.ShaderMaterial>;
  GPU_BILLBOARD: boolean;
}

export interface MeshFactory {
  createShipMesh(
    ship: Ship,
    state: GameState,
    shipsGroup: THREE.Group,
    shipMeshes: Map<number, THREE.Object3D>,
  ): THREE.Object3D;
  createBulletMesh(bullet: Bullet): THREE.Object3D;
  createHealthBarMesh(ship: Ship, factoryState: MeshFactoryState): THREE.Object3D;
  updateHealthBarMesh(ship: Ship, barGroup: THREE.Object3D): void;
  getPooledBillboardMaterial(
    color: THREE.Color,
    alpha: number,
    factoryState: MeshFactoryState,
  ): THREE.ShaderMaterial;
  disposeMeshFactory(factoryState: MeshFactoryState): void;
}

/**
 * Creates the mesh factory state
 */
export function createMeshFactoryState(): MeshFactoryState {
  return {
    billboardMaterials: new Set<THREE.ShaderMaterial>(),
    billboardMaterialPool: new Map<string, THREE.ShaderMaterial>(),
    GPU_BILLBOARD: true, // set to true to use shader-based billboarding for health bars
  };
}

/**
 * Creates a mesh for a ship with async SVG loading
 */
export function createShipMesh(
  ship: Ship,
  state: GameState,
  shipsGroup: THREE.Group,
  shipMeshes: Map<number, THREE.Object3D>,
): THREE.Object3D {
  // Defensive: ensure position values are finite before creating meshes
  const posValid =
    Number.isFinite(ship.pos?.x) && Number.isFinite(ship.pos?.y) && Number.isFinite(ship.pos?.z);
  if (!posValid) {
    try {
      logger.error('[meshFactory] createShipMesh called with invalid position for ship', {
        id: ship.id,
        pos: ship.pos,
      });
    } catch (_e) {
      void _e;
    }
    return new THREE.Group();
  }
  const pool = state.assetPool as Map<string, { imageBitmap?: ImageBitmap }> | undefined;
  const svgUrl = getShipSVGUrl(ship.class, defaultSVGConfig);

  const createTextured3DShip = (imageBitmap: ImageBitmap) => {
    const texture = new THREE.Texture(imageBitmap);
    texture.needsUpdate = true;
    texture.generateMipmaps = true;
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;

    // Create materials - textured for main surfaces, team color for others
    const teamColor = ship.team === 'red' ? 0xff4444 : 0x4444ff;
    const texturedMaterial = new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true,
      alphaTest: 0.05,
      side: THREE.DoubleSide,
    });
    const teamMaterial = new THREE.MeshBasicMaterial({
      color: teamColor,
      transparent: true,
      opacity: 0.8,
      side: THREE.DoubleSide,
    });

    // Create a group to hold the ship parts
    const shipGroup = new THREE.Group();

    const size =
      ShipVisualConfig.ships[ship.class]?.collisionRadius ?? RendererConfig.defaultCollisionRadius;

    // Main body - cylinder with SVG texture on the caps and team color on the sides
    const bodyGeometry = new THREE.CylinderGeometry(size * 0.3, size * 0.4, size * 0.8, 8);
    const bodyMaterials = [teamMaterial, texturedMaterial, texturedMaterial];
    const body = new THREE.Mesh(bodyGeometry, bodyMaterials);
    body.rotation.z = Math.PI / 2; // Orient along X-axis (nose direction)
    shipGroup.add(body);

    // Nose cone - pure team color
    const noseGeometry = new THREE.ConeGeometry(size * 0.3, size * 0.5, 8);
    const nose = new THREE.Mesh(noseGeometry, teamMaterial);
    nose.position.x = size * 0.65;
    nose.rotation.z = -Math.PI / 2; // Point along +X
    shipGroup.add(nose);

    // Wings/fins - textured planes on the sides for visibility from multiple angles
    const wingGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.4);
    const topWing = new THREE.Mesh(wingGeometry, texturedMaterial);
    topWing.position.y = size * 0.25;
    topWing.rotation.x = -Math.PI / 2;
    shipGroup.add(topWing);
    const bottomWing = new THREE.Mesh(wingGeometry, texturedMaterial);
    bottomWing.position.y = -size * 0.25;
    bottomWing.rotation.x = Math.PI / 2;
    shipGroup.add(bottomWing);

    // Side panels
    const sidePanelGeometry = new THREE.PlaneGeometry(size * 0.8, size * 0.3);
    const leftPanel = new THREE.Mesh(sidePanelGeometry, texturedMaterial);
    leftPanel.position.z = size * 0.2;
    leftPanel.rotation.y = Math.PI / 2;
    shipGroup.add(leftPanel);
    const rightPanel = new THREE.Mesh(sidePanelGeometry, texturedMaterial);
    rightPanel.position.z = -size * 0.2;
    rightPanel.rotation.y = -Math.PI / 2;
    shipGroup.add(rightPanel);

    // Rear panels and fins
    const rearPanelGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.6);
    const rearPanel = new THREE.Mesh(rearPanelGeometry, texturedMaterial);
    rearPanel.position.x = -size * 0.4;
    rearPanel.rotation.y = Math.PI;
    shipGroup.add(rearPanel);
    const rearFinGeometry = new THREE.PlaneGeometry(size * 0.3, size * 0.2);
    const topRearFin = new THREE.Mesh(rearFinGeometry, texturedMaterial);
    topRearFin.position.set(-size * 0.5, size * 0.15, 0);
    topRearFin.rotation.set(-Math.PI / 3, 0, 0);
    shipGroup.add(topRearFin);
    const bottomRearFin = new THREE.Mesh(rearFinGeometry, texturedMaterial);
    bottomRearFin.position.set(-size * 0.5, -size * 0.15, 0);
    bottomRearFin.rotation.set(Math.PI / 3, 0, 0);
    shipGroup.add(bottomRearFin);

    // Position the entire ship
    shipGroup.position.set(ship.pos.x, ship.pos.y, ship.pos.z);
    return shipGroup;
  };

  // If we already have an asset in pool, build textured ship from it
  try {
    if (pool && pool.has(svgUrl)) {
      const svgAsset = pool.get(svgUrl);
      if (svgAsset?.imageBitmap) return createTextured3DShip(svgAsset.imageBitmap);
    }
  } catch (_e) {
    void _e; /* ignore */
  }

  // Fallback placeholder, and kick off async load to replace visual when ready
  const geom = new THREE.ConeGeometry(8, 24, 8);
  const mat = new THREE.MeshPhongMaterial({
    color: colorForTeam(ship.team),
    emissive: 0x111122,
  });
  const placeholder = new THREE.Mesh(geom, mat);
  placeholder.rotation.z = 0; // Will be set correctly in updateTransforms
  placeholder.position.set(ship.pos.x, ship.pos.y, ship.pos.z);

  // Lazy-load SVG and swap geometry/material once available
  (async () => {
    try {
      // If GLTF models are enabled and a glTF prototype exists in the asset pool, skip SVG rasterization.
      try {
        const shouldUseGltf = (RendererConfig as any)?.loadGltfModels ?? false;
        if (shouldUseGltf && state && state.assetPool) {
          const gltfKeyTeam = `ship-${ship.class}-${ship.team}`;
          const gltfKey = `ship-${ship.class}`;
          const proto = state.assetPool.get(gltfKeyTeam) ?? state.assetPool.get(gltfKey);
          if (proto && typeof proto === 'object') {
            // Register prototype if threePrototypes exist, or allocate a marker so instancing can proceed
            try {
              shipInstancer.allocate(ship.id, ship.class, ship.team, state);
            } catch (_) {
              void _;
            }
            return; // skip SVG rasterization
          }
        }
      } catch (_e) {
        void _e;
      }
      // If SVG subsystem is disabled, skip rasterization and keep placeholder
      if ((RendererConfig as any)?.disableSvgSubsystem) {
        logger.debug('[meshFactory] SVG subsystem disabled; skipping rasterization for', svgUrl);
        return; // keep placeholder
      }

      const teamColor =
        ship.team === 'red' ? defaultSVGConfig.teamColors.red : defaultSVGConfig.teamColors.blue;
      const asset = await loadSVGAsset(svgUrl, {
        width: defaultSVGConfig.defaultRasterSize.width,
        height: defaultSVGConfig.defaultRasterSize.height,
        teamColor: teamColor,
      });
      if (pool) pool.set(svgUrl, asset);
      if (asset?.imageBitmap && placeholder.parent) {
        // Build a representative list of geometries and materials matching the textured ship parts.
        try {
          const teamColor = ship.team === 'red' ? 0xff4444 : 0x4444ff;
          const texturedMaterial = new THREE.MeshBasicMaterial({
            map: new THREE.Texture(asset.imageBitmap),
            transparent: true,
            alphaTest: 0.05,
            side: THREE.DoubleSide,
          });
          texturedMaterial.map!.needsUpdate = true;
          const teamMaterial = new THREE.MeshBasicMaterial({
            color: teamColor,
            transparent: true,
            opacity: 0.8,
            side: THREE.DoubleSide,
          });

          const size =
            ShipVisualConfig.ships[ship.class]?.collisionRadius ??
            RendererConfig.defaultCollisionRadius;
          const bodyGeometry = new THREE.CylinderGeometry(size * 0.3, size * 0.4, size * 0.8, 8);
          const noseGeometry = new THREE.ConeGeometry(size * 0.3, size * 0.5, 8);
          const wingGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.4);
          const sidePanelGeometry = new THREE.PlaneGeometry(size * 0.8, size * 0.3);
          const rearPanelGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.6);
          const rearFinGeometry = new THREE.PlaneGeometry(size * 0.3, size * 0.2);

          const geoms = [
            bodyGeometry,
            noseGeometry,
            wingGeometry,
            wingGeometry,
            sidePanelGeometry,
            sidePanelGeometry,
            rearPanelGeometry,
            rearFinGeometry,
            rearFinGeometry,
          ];
          const mats = [
            texturedMaterial,
            teamMaterial,
            texturedMaterial,
            texturedMaterial,
            texturedMaterial,
            texturedMaterial,
            texturedMaterial,
            texturedMaterial,
            texturedMaterial,
          ];

          // Register prototype for the instancer so future ships of this class can use instancing.
          shipInstancer.registerPrototype(ship.class, geoms, mats);

          // If instancing is enabled and we can allocate for this existing ship, migrate the placeholder
          // to an instanced slot instead of adding a non-instanced textured mesh.
          if (RendererConfig.instancing.enableShips) {
            try {
              const allocated = shipInstancer.allocate(ship.id, ship.class, ship.team, state);
              if (allocated) {
                // Immediately set transform so the instance appears in the correct place
                const q = new THREE.Quaternion();
                q.setFromEuler(
                  new THREE.Euler(
                    ship.orientation.pitch,
                    ship.orientation.yaw,
                    ship.orientation.roll,
                  ),
                );
                const scale =
                  ShipVisualConfig.ships[ship.class]?.scale ?? RendererConfig.defaultScale;
                shipInstancer.updateTransform(ship.id, ship.pos, q, scale);
                // Remove placeholder from scene and track a lightweight object in the mesh map
                try {
                  if (placeholder.parent) placeholder.parent.remove(placeholder);
                } catch (_e) {
                  void _e; /* ignore */
                }
                shipMeshes.set(ship.id, new THREE.Object3D());
                // Don't add the textured non-instanced mesh
                return;
              }
            } catch (e) {
              void e;
              logger.warn('shipInstancer.allocate during migration failed', e as unknown);
            }
          }

          // Fallback: create full textured mesh and replace placeholder
          const ship3D = createTextured3DShip(asset.imageBitmap);
          ship3D.position.copy(placeholder.position);
          shipsGroup.add(ship3D);
          shipsGroup.remove(placeholder);
          shipMeshes.set(ship.id, ship3D);
        } catch (e) {
          void e;
          logger.warn('shipInstancer.allocate during migration failed', e as unknown);
          logger.warn('shipInstancer.registerPrototype or migration failed', e as unknown);
          const ship3D = createTextured3DShip(asset.imageBitmap);
          ship3D.position.copy(placeholder.position);
          shipsGroup.add(ship3D);
          shipsGroup.remove(placeholder);
          shipMeshes.set(ship.id, ship3D);
        }
      }
    } catch (e) {
      void e; // Loading/parsing of SVG failed — log and keep placeholder
      logger.error('Failed to load SVG asset for ship', e as unknown);
    }
  })();

  // Return placeholder while async asset loads
  return placeholder;
}

/**
 * Register instancer prototypes from preloaded assets in the state's asset pool.
 * This builds the same geometries/materials used by `createShipMesh` and calls
 * `shipInstancer.registerPrototype` so instanced allocations will have correct visuals.
 */
export function registerPrototypesFromPool(state: GameState) {
  try {
    const pool = state.assetPool as Map<string, { imageBitmap?: ImageBitmap }> | undefined;
    if (!pool) return;
    const classes: ShipClass[] = ['fighter', 'corvette', 'frigate', 'destroyer', 'carrier'];
    for (const cls of classes) {
      // First, attempt to register any glTF-derived threePrototypes found in the asset pool.
      try {
        try {
          const teamsToCheck = ['red', 'blue'];
          let gltfProto: unknown | undefined;
          for (const t of teamsToCheck) {
            const key = `ship-${cls}-${t}`;
            const p = pool.get(key) as unknown | undefined;
            if (p) {
              gltfProto = p;
              break;
            }
          }
          if (!gltfProto) gltfProto = pool.get(`ship-${cls}`) as unknown | undefined;
          if (gltfProto && typeof gltfProto === 'object') {
            const tp = (
              gltfProto as unknown as {
                threePrototypes?: { geometries?: unknown[]; materials?: unknown[] };
              }
            ).threePrototypes;
            if (
              tp &&
              Array.isArray(tp.geometries) &&
              Array.isArray(tp.materials) &&
              tp.geometries.length > 0
            ) {
              // Clone geometries/materials defensively before registering
              const clonedGeoms: THREE.BufferGeometry[] = [];
              const clonedMats: THREE.Material[] = [];
              for (let i = 0; i < tp.geometries.length; i++) {
                try {
                  const g = tp.geometries[i] as unknown;
                  const geom =
                    g && typeof (g as unknown as { clone?: unknown }).clone === 'function'
                      ? ((g as unknown as { clone: () => unknown }).clone() as THREE.BufferGeometry)
                      : (g as unknown as THREE.BufferGeometry);
                  clonedGeoms.push(geom);
                } catch (_e) {
                  void _e;
                }
              }
              for (let i = 0; i < tp.materials.length; i++) {
                try {
                  const m = tp.materials[i] as unknown;
                  const mat =
                    m && typeof (m as unknown as { clone?: unknown }).clone === 'function'
                      ? ((m as unknown as { clone: () => unknown }).clone() as THREE.Material)
                      : (m as unknown as THREE.Material);
                  clonedMats.push(mat);
                } catch (_e) {
                  void _e;
                }
              }
              // Prefer updatePrototype if available so existing groups are updated in-place
              const up = (
                shipInstancer as unknown as {
                  updatePrototype?: (
                    name: string,
                    geoms: THREE.BufferGeometry[],
                    mats: THREE.Material[],
                  ) => void;
                }
              ).updatePrototype;
              if (typeof up === 'function') {
                try {
                  up(cls, clonedGeoms, clonedMats);
                } catch (_e) {
                  void _e;
                  shipInstancer.registerPrototype(cls, clonedGeoms, clonedMats);
                }
              } else {
                shipInstancer.registerPrototype(cls, clonedGeoms, clonedMats);
              }
              // Ensure team groups exist so allocate() can find them deterministically
              try {
                shipInstancer.ensureGroup?.(cls, 'red');
              } catch (_e) {
                void _e;
              }
              try {
                shipInstancer.ensureGroup?.(cls, 'blue');
              } catch (_e) {
                void _e;
              }
              if (logger && typeof logger.info === 'function')
                logger.info(`meshFactory: registered glTF instancer prototype for ${cls}`);
            }
          }
        } catch (_e) {
          void _e;
        }
      } catch (_e) {
        void _e;
      }

      try {
        const svgUrl = getShipSVGUrl(cls, defaultSVGConfig);
        const asset = pool.get(svgUrl) as { imageBitmap?: ImageBitmap } | undefined;
        if (!asset?.imageBitmap) continue;

        const tex = new THREE.Texture(asset.imageBitmap);
        tex.needsUpdate = true;
        tex.generateMipmaps = false;
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;

        const texturedMaterial = new THREE.MeshBasicMaterial({
          map: tex,
          transparent: true,
          alphaTest: 0.05,
          side: THREE.DoubleSide,
        });
        const teamMaterial = new THREE.MeshBasicMaterial({
          color: 0xffffff,
          transparent: true,
          opacity: 1.0,
          side: THREE.DoubleSide,
        });

        const size =
          ShipVisualConfig.ships[cls]?.collisionRadius ?? RendererConfig.defaultCollisionRadius;
        const bodyGeometry = new THREE.CylinderGeometry(size * 0.3, size * 0.4, size * 0.8, 8);
        const noseGeometry = new THREE.ConeGeometry(size * 0.3, size * 0.5, 8);
        const wingGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.4);
        const sidePanelGeometry = new THREE.PlaneGeometry(size * 0.8, size * 0.3);
        const rearPanelGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.6);
        const rearFinGeometry = new THREE.PlaneGeometry(size * 0.3, size * 0.2);

        const geoms = [
          bodyGeometry,
          noseGeometry,
          wingGeometry,
          wingGeometry,
          sidePanelGeometry,
          sidePanelGeometry,
          rearPanelGeometry,
          rearFinGeometry,
          rearFinGeometry,
        ];
        const mats = [
          texturedMaterial,
          teamMaterial,
          texturedMaterial,
          texturedMaterial,
          texturedMaterial,
          texturedMaterial,
          texturedMaterial,
          texturedMaterial,
          texturedMaterial,
        ];

        try {
          // Prefer updatePrototype to replace any existing group meshes immediately
          const up = (
            shipInstancer as unknown as {
              updatePrototype?: (
                name: string,
                geoms: THREE.BufferGeometry[],
                mats: THREE.Material[],
              ) => void;
            }
          ).updatePrototype;
          if (typeof up === 'function') {
            try {
              up(cls, geoms, mats);
            } catch (err) {
              void err;
              shipInstancer.registerPrototype(cls, geoms, mats);
            }
          } else {
            shipInstancer.registerPrototype(cls, geoms, mats);
          }
          if (logger && typeof logger.info === 'function')
            logger.info(`meshFactory: registered instancer prototype for ${cls}`);
          // Ensure both team groups exist (dev/diagnostic) by creating empty groups
          try {
            if (RendererConfig.instancing.enableShips) {
              try {
                (
                  shipInstancer as unknown as {
                    ensureGroup?: (name: string, team?: string) => void;
                  }
                ).ensureGroup?.(cls, 'red');
              } catch (_e) {
                void _e;
              }
              try {
                (
                  shipInstancer as unknown as {
                    ensureGroup?: (name: string, team?: string) => void;
                  }
                ).ensureGroup?.(cls, 'blue');
              } catch (_e) {
                void _e;
              }
            }
          } catch (_e) {
            void _e;
          }
        } catch (_e) {
          void _e;
        }
      } catch (_e) {
        void _e;
      }
    }
  } catch (_e) {
    void _e;
  }
}

/**
 * Creates a mesh for a bullet
 */
export function createBulletMesh(bullet: Bullet): THREE.Object3D {
  // Defensive: validate bullet position
  const posValid =
    Number.isFinite(bullet.pos?.x) &&
    Number.isFinite(bullet.pos?.y) &&
    Number.isFinite(bullet.pos?.z);
  if (!posValid) {
    try {
      logger.error('[meshFactory] createBulletMesh invalid pos', {
        id: bullet.id,
        pos: bullet.pos,
      });
    } catch (_e) {
      void _e;
    }
    return new THREE.Group();
  }

  const geom = new THREE.SphereGeometry(2.2, 8, 8);
  const mat = new THREE.MeshBasicMaterial({ color: 0xffdd88 });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.set(bullet.pos.x, bullet.pos.y, bullet.pos.z);
  return mesh;
}

/**
 * Creates a health bar mesh with background, health, and shield components
 */
export function createHealthBarMesh(ship: Ship, factoryState: MeshFactoryState): THREE.Object3D {
  // Defensive guard: avoid creating health bar visuals for unknown/invalid ship entries
  const hasKnownClass = !!ShipVisualConfig.ships[ship.class as keyof typeof ShipVisualConfig.ships];
  const posValid =
    Number.isFinite(ship.pos?.x) && Number.isFinite(ship.pos?.y) && Number.isFinite(ship.pos?.z);
  if (!hasKnownClass || !posValid) {
    // Return an empty group as a no-op to callers expecting an Object3D
    return new THREE.Group();
  }

  // DEV LOG: record creation of a non-instanced health bar via meshFactory
  try {
    console.info(
      `[HB_TRACE][meshFactory] createHealthBarMesh for ship=${ship.id} class=${ship.class} pos=(${ship.pos.x},${ship.pos.y},${ship.pos.z})`,
    );
    try {
      console.info(new Error('HB_STACK createHealthBarMesh').stack);
    } catch (_e) {
      void _e;
    }
  } catch (_e) {
    void _e;
  }

  const config = RendererConfig.healthBars;
  const barGroup = new THREE.Group();

  // Background bar
  const bgGeom = new THREE.PlaneGeometry(config.width, config.position.height);
  let bgMat: THREE.Material;
  if (factoryState.GPU_BILLBOARD) {
    const mat = getPooledBillboardMaterial(
      new THREE.Color(config.colors.background),
      1.0,
      factoryState,
    );
    bgMat = mat;
  } else {
    bgMat = new THREE.MeshBasicMaterial({ color: config.colors.background });
  }
  const bgMesh = new THREE.Mesh(bgGeom, bgMat);
  barGroup.add(bgMesh);

  // Health bar
  const healthGeom = new THREE.PlaneGeometry(config.width - 2, config.position.height - 2);
  let healthMat: THREE.Material;
  if (factoryState.GPU_BILLBOARD) {
    const mat = getPooledBillboardMaterial(
      new THREE.Color(config.colors.health.full),
      1.0,
      factoryState,
    );
    healthMat = mat;
  } else {
    healthMat = new THREE.MeshBasicMaterial({ color: config.colors.health.full });
  }
  const healthMesh = new THREE.Mesh(healthGeom, healthMat);
  barGroup.add(healthMesh);

  // Shield bar (if ship has shield)
  let shieldMesh: THREE.Mesh | null = null;
  if (ship.maxShield > 0) {
    const shieldGeom = new THREE.PlaneGeometry(config.width - 2, config.position.height - 2);
    let shieldMat: THREE.Material;
    if (factoryState.GPU_BILLBOARD) {
      const mat = getPooledBillboardMaterial(
        new THREE.Color(config.colors.shield.full),
        0.8,
        factoryState,
      );
      shieldMat = mat;
    } else {
      shieldMat = new THREE.MeshBasicMaterial({
        color: config.colors.shield.full,
        transparent: true,
        opacity: 0.8,
      });
    }
    shieldMesh = new THREE.Mesh(shieldGeom, shieldMat);
    shieldMesh.position.z = 0.1; // slightly in front
    barGroup.add(shieldMesh);
  }

  // Border
  const borderGeom = new THREE.RingGeometry(
    config.width / 2 - config.border.width / 2,
    config.width / 2 + config.border.width / 2,
    8,
  );
  const borderMat = new THREE.MeshBasicMaterial({
    color: config.border.color,
    transparent: true,
    opacity: 0.5,
  });
  const borderMesh = new THREE.Mesh(borderGeom, borderMat);
  borderMesh.position.z = 0.2;
  barGroup.add(borderMesh);

  // Store references for updating
  const barRef = barGroup as unknown as {
    healthMesh?: THREE.Mesh;
    shieldMesh?: THREE.Mesh | null;
    bgMesh?: THREE.Mesh;
  };
  barRef.healthMesh = healthMesh;
  barRef.shieldMesh = shieldMesh;
  barRef.bgMesh = bgMesh;

  return barGroup;
}

/**
 * Updates the health bar mesh based on ship status
 */
export function updateHealthBarMesh(ship: Ship, barGroup: THREE.Object3D): void {
  const config = RendererConfig.healthBars;
  const barRef = barGroup as unknown as { healthMesh?: THREE.Mesh; shieldMesh?: THREE.Mesh | null };
  const healthMesh = barRef.healthMesh as THREE.Mesh;
  const shieldMesh = barRef.shieldMesh as THREE.Mesh | null;

  // Position the bar above the ship (3D)
  barGroup.position.set(
    ship.pos.x + config.position.offsetX,
    ship.pos.y + config.position.offsetY,
    ship.pos.z + ShipVisualConfig.healthBar.offset.z, // Above the ship
  );

  // Update health bar
  const healthPercent = ship.health / ship.maxHealth;
  healthMesh.scale.x = Math.max(0, healthPercent);

  // Update health color based on percentage
  const healthColor =
    healthPercent > 0.5 ? config.colors.health.full : config.colors.health.damaged;
  if (healthMesh.material) {
    const mat = healthMesh.material as THREE.ShaderMaterial;
    if (mat.uniforms && mat.uniforms.uColor) {
      (mat.uniforms.uColor.value as THREE.Color).set(healthColor);
    } else if ((healthMesh.material as THREE.MeshBasicMaterial).color) {
      (healthMesh.material as THREE.MeshBasicMaterial).color.set(healthColor);
    }
  }

  // Update shield bar
  if (shieldMesh && ship.maxShield > 0) {
    const shieldPercent = ship.shield / ship.maxShield;
    shieldMesh.scale.x = Math.max(0, shieldPercent);

    const shieldColor =
      shieldPercent > 0.5 ? config.colors.shield.full : config.colors.shield.damaged;
    if (shieldMesh.material) {
      const mat = shieldMesh.material as THREE.ShaderMaterial;
      if (mat.uniforms && mat.uniforms.uColor) {
        (mat.uniforms.uColor.value as THREE.Color).set(shieldColor);
      } else if ((shieldMesh.material as THREE.MeshBasicMaterial).color) {
        (shieldMesh.material as THREE.MeshBasicMaterial).color.set(shieldColor);
      }
    }
  }
}

/**
 * Get or create a pooled ShaderMaterial for the given color/alpha
 */
export function getPooledBillboardMaterial(
  color: THREE.Color = new THREE.Color(0xffffff),
  alpha: number = 1.0,
  factoryState: MeshFactoryState,
): THREE.ShaderMaterial {
  const key = billboardPoolKey(color, alpha);
  const existing = factoryState.billboardMaterialPool.get(key);
  if (existing) return existing;

  const mat = new THREE.ShaderMaterial({
    uniforms: {
      cameraRight: { value: new THREE.Vector3(1, 0, 0) },
      cameraUp: { value: new THREE.Vector3(0, 1, 0) },
      uColor: { value: color.clone() },
      uAlpha: { value: alpha },
    },
    vertexShader: billboardVertexShader,
    fragmentShader: billboardFragmentShader,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  // Avoid depth-test issues for overlapping transparent billboards
  (mat as THREE.ShaderMaterial & { depthTest?: boolean }).depthTest = false;
  factoryState.billboardMaterialPool.set(key, mat);
  factoryState.billboardMaterials.add(mat);
  return mat;
}

/**
 * Helper: compute a key for the material pool based on color and alpha
 */
function billboardPoolKey(color: THREE.Color, alpha: number): string {
  // Use CSS hex + alpha to key materials
  return `${color.getHexString()}|${alpha}`;
}

/**
 * Billboard shader: place quad in world space using camera right/up vectors so it always faces the camera.
 */
const billboardVertexShader = `
  uniform vec3 cameraRight;
  uniform vec3 cameraUp;
  uniform float uAlpha;
  uniform vec3 uColor;

  varying vec3 vColor;
  varying float vAlpha;

  void main() {
    // center of this object in world-space
    vec3 center = (modelMatrix * vec4(0.0, 0.0, 0.0, 1.0)).xyz;
    // position.xy are the local quad coords (e.g., -w/2..w/2, -h/2..h/2)
    vec3 worldPos = center + cameraRight * position.x + cameraUp * position.y;
    gl_Position = projectionMatrix * viewMatrix * vec4(worldPos, 1.0);
    vColor = uColor;
    vAlpha = uAlpha;
  }
`;

const billboardFragmentShader = `
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    gl_FragColor = vec4(vColor, vAlpha);
  }
`;

/**
 * Helper function to get team color
 */
function colorForTeam(team: 'red' | 'blue'): number {
  return team === 'red' ? 0xff5050 : 0x50a0ff;
}

/**
 * Disposes mesh factory resources
 */
export function disposeMeshFactory(factoryState: MeshFactoryState): void {
  // Dispose pooled billboard materials
  for (const mat of factoryState.billboardMaterialPool.values()) {
    try {
      mat.dispose();
    } catch (_e) {
      void _e; /* ignore */
    }
  }
  factoryState.billboardMaterialPool.clear();
  factoryState.billboardMaterials.clear();
}

/**
 * Default mesh factory implementation
 */
export const meshFactory: MeshFactory = {
  createShipMesh,
  createBulletMesh,
  createHealthBarMesh,
  updateHealthBarMesh,
  getPooledBillboardMaterial,
  disposeMeshFactory,
};

/**
 * Billboard Explosion Shader
 *
 * Reference additive billboard shader for particle explosions with configurable
 * color stops, size, and soft-edge falloff parameters.
 *
 * Features:
 * - Automatic camera-facing billboarding
 * - Configurable color interpolation over lifetime
 * - Soft-edge falloff from texture alpha
 * - Additive blending for realistic fire/explosion effects
 * - Integration with colorOverride system
 */

export const billboardExplosionVertexShader = `
  // Standard vertex attributes
  attribute vec3 position;
  attribute vec2 uv;

  // Per-instance attributes (for instanced rendering)
  attribute vec3 instancePosition;
  attribute float instanceSize;
  attribute vec4 instanceColor;
  attribute float instanceAge;
  attribute float instanceLifetime;

  // Standard uniforms
  uniform mat4 modelViewMatrix;
  uniform mat4 projectionMatrix;
  uniform mat4 viewMatrix;
  uniform vec3 cameraPosition;

  // Shader parameters
  uniform float billboardScale;

  // Varyings to fragment shader
  varying vec2 vUv;
  varying vec4 vColor;
  varying float vLifeRatio;
  varying float vFadeAlpha;

  void main() {
    vUv = uv;
    vColor = instanceColor;

    // Calculate normalized lifetime (0.0 = birth, 1.0 = death)
    vLifeRatio = clamp(instanceAge / max(instanceLifetime, 0.001), 0.0, 1.0);

    // Billboard calculation - always face the camera
    vec3 worldPosition = instancePosition;

    // Get camera forward vector (negative Z in view space)
    vec3 cameraForward = -normalize((viewMatrix * vec4(0.0, 0.0, -1.0, 0.0)).xyz);
    vec3 cameraUp = normalize((viewMatrix * vec4(0.0, 1.0, 0.0, 0.0)).xyz);
    vec3 cameraRight = normalize(cross(cameraForward, cameraUp));

    // Apply billboard scale and instance size
    float finalSize = instanceSize * billboardScale;

    // Calculate billboard vertex position
    vec3 localPosition = cameraRight * position.x * finalSize + cameraUp * position.y * finalSize;
    vec4 worldPos = vec4(worldPosition + localPosition, 1.0);

    // Calculate fade based on distance to camera (optional LOD)
    float distanceToCamera = length(cameraPosition - worldPosition);
    vFadeAlpha = 1.0; // Can be modified for distance-based fading

    gl_Position = projectionMatrix * modelViewMatrix * worldPos;
  }
`;

export const billboardExplosionFragmentShader = `
  // Uniforms for texture and color control
  uniform sampler2D explosionTexture;
  uniform float fadeInDuration;
  uniform float fadeOutStart;
  uniform float softEdgePower;
  uniform float colorIntensity;

  // Color stops for lifetime interpolation
  uniform vec3 colorStop1;    // Birth color (t=0.0)
  uniform vec3 colorStop2;    // Mid-life color (t=0.5)
  uniform vec3 colorStop3;    // Death color (t=1.0)
  uniform float colorStop1Pos;
  uniform float colorStop2Pos;
  uniform float colorStop3Pos;

  // Varyings from vertex shader
  varying vec2 vUv;
  varying vec4 vColor;
  varying float vLifeRatio;
  varying float vFadeAlpha;

  /**
   * Interpolate between three color stops based on normalized time
   * Uses smoothstep for smooth transitions between stops
   */
  vec3 interpolateColorStops(float t) {
    // Normalize positions to ensure proper interpolation
    float pos1 = clamp(colorStop1Pos, 0.0, 1.0);
    float pos2 = clamp(colorStop2Pos, pos1, 1.0);
    float pos3 = clamp(colorStop3Pos, pos2, 1.0);

    if (t <= pos1) {
      return colorStop1;
    } else if (t <= pos2) {
      float factor = smoothstep(pos1, pos2, t);
      return mix(colorStop1, colorStop2, factor);
    } else {
      float factor = smoothstep(pos2, pos3, t);
      return mix(colorStop2, colorStop3, factor);
    }
  }

  /**
   * Calculate alpha fade-in and fade-out over particle lifetime
   */
  float calculateLifetimeFade(float t) {
    // Fade in from birth
    float fadeIn = smoothstep(0.0, fadeInDuration, t);

    // Fade out approaching death
    float fadeOut = 1.0 - smoothstep(fadeOutStart, 1.0, t);

    return fadeIn * fadeOut;
  }

  void main() {
    // Sample the explosion texture (should be soft-circle or similar)
    vec4 texColor = texture2D(explosionTexture, vUv);

    // Calculate color based on particle lifetime
    vec3 dynamicColor = interpolateColorStops(vLifeRatio);

    // Apply color override from instance (if provided) or use dynamic color
    // vColor.rgb contains the override color or default white
    vec3 finalColor = dynamicColor * vColor.rgb * colorIntensity;

    // Calculate alpha components
    float lifetimeFade = calculateLifetimeFade(vLifeRatio);
    float textureAlpha = pow(texColor.r, softEdgePower); // Use red channel as luminance
    float instanceAlpha = vColor.a * vFadeAlpha;

    // Combine all alpha contributions
    float finalAlpha = textureAlpha * instanceAlpha * lifetimeFade;

    // Apply soft-edge falloff - additional radial fade for smoother edges
    vec2 center = vUv - 0.5;
    float radialDistance = length(center) * 2.0; // 0.0 at center, 1.0 at edge
    float radialFade = 1.0 - smoothstep(0.7, 1.0, radialDistance);
    finalAlpha *= radialFade;

    gl_FragColor = vec4(finalColor, finalAlpha);
  }
`;

/**
 * Shader parameter configuration
 * Maps to uniforms and provides sensible defaults
 */
export interface BillboardExplosionShaderParams {
  // Texture
  explosionTexture?: WebGLTexture;

  // Timing parameters
  fadeInDuration?: number; // How quickly particle fades in (0.0-1.0)
  fadeOutStart?: number; // When fade-out begins (0.0-1.0)

  // Visual parameters
  billboardScale?: number; // Overall size multiplier
  softEdgePower?: number; // Power for soft-edge falloff (higher = sharper)
  colorIntensity?: number; // Overall color intensity multiplier

  // Color stops (vec3 RGB values 0.0-1.0)
  colorStop1?: [number, number, number]; // Birth color
  colorStop2?: [number, number, number]; // Mid-life color
  colorStop3?: [number, number, number]; // Death color

  // Color stop positions (0.0-1.0)
  colorStop1Pos?: number;
  colorStop2Pos?: number;
  colorStop3Pos?: number;
}

/**
 * Default shader parameters
 * Provides fire-like explosion effect with smooth transitions
 */
export const DefaultBillboardExplosionParams: Required<BillboardExplosionShaderParams> = {
  // Texture will be set by renderer
  explosionTexture: null as any,

  // Timing - quick fade-in, long visibility, gradual fade-out
  fadeInDuration: 0.1,
  fadeOutStart: 0.7,

  // Visual - moderate billboard scale, soft edges, full intensity
  billboardScale: 1.0,
  softEdgePower: 2.2, // Gamma-corrected falloff
  colorIntensity: 1.2, // Slightly brighter for additive blending

  // Color stops - fire-like progression from white-hot to dark red
  colorStop1: [1.0, 0.98, 0.85], // Bright white-yellow (birth)
  colorStop2: [1.0, 0.55, 0.0], // Orange (mid-life)
  colorStop3: [0.27, 0.0, 0.0], // Dark red (death)

  // Color stop positions - even distribution with emphasis on mid-life
  colorStop1Pos: 0.0,
  colorStop2Pos: 0.4,
  colorStop3Pos: 1.0,
};

