          ctx.beginPath();
          ctx.arc(s.x + 0.5, s.y + 0.5, s.size / 2, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      ctx.globalAlpha = 1.0;
      texture.needsUpdate = true;
    });

