import type { GameState, UIElements } from '../types/index.js';
import { resetState, spawnFleet, spawnShip } from '../core/gameState.js';
import { reFormFleets } from '../core/reFormFleets.js';
import { randomClass } from '../utils/randomShipClass.js';
import { RendererConfig } from '../config/rendererConfig.js';
import { FleetConfig } from '../config/fleetConfig.js';

export function wireControls(state: GameState, ui: UIElements): void {
  function updateSpeedLabel() {
    ui.speed.textContent = `Speed: ${state.speedMultiplier}×`;
  }
  function updateRunLabel() {
    ui.startPause.textContent = state.running ? '⏸ Pause' : '▶ Start';
  }
  function updateScores() {
    ui.redScore.textContent = `Red ${state.score.red}`;
    ui.blueScore.textContent = `Blue ${state.score.blue}`;
  }

  ui.startPause.onclick = () => {
    state.running = !state.running;
    updateRunLabel();
  };
  ui.reset.onclick = () => {
    resetState(state);
    spawnFleet(state, 'red', FleetConfig.spawning.defaultFleetSize);
    spawnFleet(state, 'blue', FleetConfig.spawning.defaultFleetSize);
    reFormFleets(state);
    updateScores();
  };
  ui.addRed.onclick = () => {
    spawnShip(state, 'red', randomClass(state));
  };
  ui.addBlue.onclick = () => {
    spawnShip(state, 'blue', randomClass(state));
  };
  ui.toggleTrails.onclick = () => {
    RendererConfig.visual.enableTrails = !RendererConfig.visual.enableTrails;
    ui.toggleTrails.textContent = `☄ Trails: ${RendererConfig.visual.enableTrails ? 'On' : 'Off'}`;
  };
  ui.speed.onclick = () => {
    const seq = [0.5, 1, 2, 4] as const;
    const i = seq.indexOf(state.speedMultiplier as any);
    const next = seq[(i + 1) % seq.length];
    state.speedMultiplier = next;
    updateSpeedLabel();
  };
  ui.seedBtn.onclick = () => {
    const s = `SEED-${Date.now()}`;
    resetState(state, s);
    spawnFleet(state, 'red', FleetConfig.spawning.defaultFleetSize);
    spawnFleet(state, 'blue', FleetConfig.spawning.defaultFleetSize);
    reFormFleets(state);
    updateScores();
  };
  ui.formationBtn.onclick = () => {
    state.ships = [];
    state.bullets = [];
    const fleetSize = FleetConfig.spawning.defaultFleetSize;
    for (let i = 0; i < fleetSize; i++) {
      const redClass = randomClass(state);
      const blueClass = randomClass(state);
      spawnShip(state, 'red', redClass);
      spawnShip(state, 'blue', blueClass);
    }
    updateScores();
  };

  updateSpeedLabel();
  updateRunLabel();
  updateScores();
}

// File Watcher Utility for detecting SVG file changes
import * as logger from './logger.js';
// Provides change detection for hot-reloading SVG assets

export interface FileChangeCallback {
  (filePath: string, changeType: 'modified' | 'deleted' | 'created'): void;
}

export class FileWatcher {
  private watchers = new Map<string, FileChangeCallback>();
  private pollIntervals = new Map<string, number>();
  private lastModifiedTimes = new Map<string, number>();
  private pollInterval = 1000; // Check every second
  // When true, the watcher will perform a single check at watch() time
  // and then not start continuous polling. This is safer for production
  // builds where assets are static and avoids continuous HEAD requests.
  private oneShotMode = true;

  // Watch a file for changes
  watch(filePath: string, callback: FileChangeCallback): void {
    // Stop existing watcher if any
    this.unwatch(filePath);

    // If this is a standalone inlined build and the file is an inlined SVG,
    // don't start the network polling — treat it as created and use a
    // surrogate mod-time. This avoids any HEAD requests entirely.
    try {
      const standalone =
        (typeof globalThis !== 'undefined' ? (globalThis as any).__STANDALONE : undefined) ||
        (typeof window !== 'undefined' ? (window as any).__STANDALONE : undefined);
      const inlineAssets =
        (typeof globalThis !== 'undefined' ? (globalThis as any).__INLINE_SVG_ASSETS : undefined) ||
        (typeof window !== 'undefined' ? (window as any).__INLINE_SVG_ASSETS : undefined);
      if (standalone && inlineAssets && typeof filePath === 'string' && filePath.endsWith('.svg')) {
        this.watchers.set(filePath, callback);
        const cleaned = filePath.split(/[?#]/)[0];
        const m = cleaned.match(/([^/]+)\.svg$/);
        const name = m ? m[1] : null;
        if (name && inlineAssets[name]) {
          // Treat as created with current time and don't start interval
          this.lastModifiedTimes.set(filePath, Date.now());
          // Notify immediately as created
          this.notifyChange(filePath, 'created');
          return;
        }
      }
    } catch (_e) {
      void _e; // ignore and fall back to normal behavior
    }

    this.watchers.set(filePath, callback);

    // Get initial modification time
    this.checkFile(filePath).then((modTime) => {
      if (modTime !== null) {
        this.lastModifiedTimes.set(filePath, modTime);
      }
    });

    // Start polling only when not in one-shot mode
    if (!this.oneShotMode) {
      const intervalId = setInterval(() => {
        this.checkFile(filePath);
      }, this.pollInterval) as unknown as number;

      this.pollIntervals.set(filePath, intervalId);
    }
  }

  // Stop watching a file
  unwatch(filePath: string): void {
    const intervalId = this.pollIntervals.get(filePath);
    if (intervalId) {
      clearInterval(intervalId);
      this.pollIntervals.delete(filePath);
    }

    this.watchers.delete(filePath);
    this.lastModifiedTimes.delete(filePath);
  }

  // Check if a file has changed
  private async checkFile(filePath: string): Promise<number | null> {
    try {
      const modTime = await this.getFileModificationTime(filePath);
      if (modTime === null) {
        // File doesn't exist or can't be accessed
        const lastKnownTime = this.lastModifiedTimes.get(filePath);
        if (lastKnownTime !== undefined) {
          // File was deleted
          this.notifyChange(filePath, 'deleted');
          this.unwatch(filePath);
        }
        return null;
      }

      const lastModTime = this.lastModifiedTimes.get(filePath);
      if (lastModTime === undefined) {
        // First time seeing this file
        this.lastModifiedTimes.set(filePath, modTime);
        this.notifyChange(filePath, 'created');
      } else if (modTime > lastModTime) {
        // File was modified
        this.lastModifiedTimes.set(filePath, modTime);
        this.notifyChange(filePath, 'modified');
      }

      return modTime;
    } catch (_error) {
      void _error; // Use centralized logger
      try {
        logger.warn(`[FileWatcher] Error checking file ${filePath}:`, _error);
      } catch (_e) {
        void _e;
        void _e;
      }
      return null;
    }
  }

  // Get file modification time
  private async getFileModificationTime(filePath: string): Promise<number | null> {
    try {
      // If the app has inlined SVG assets (standalone), skip network HEAD checks
      // for those assets to avoid aborted HEAD requests in the browser.
      try {
        logger.debug && logger.debug('[FileWatcher] getFileModificationTime called for', filePath);
        // If the runtime was produced by the standalone inliner, honor the
        // explicit standalone flag and short-circuit any network HEAD checks
        // for SVG assets. This prevents browsers from issuing transient HEAD
        // requests (which can be aborted) when assets are embedded.
        const standalone =
          (typeof globalThis !== 'undefined' ? (globalThis as any).__STANDALONE : undefined) ||
          (typeof window !== 'undefined' ? (window as any).__STANDALONE : undefined);
        const inlineAssets =
          (typeof globalThis !== 'undefined'
            ? (globalThis as any).__INLINE_SVG_ASSETS
            : undefined) ||
          (typeof window !== 'undefined' ? (window as any).__INLINE_SVG_ASSETS : undefined);
        if (
          standalone &&
          inlineAssets &&
          typeof filePath === 'string' &&
          filePath.endsWith('.svg')
        ) {
          const cleaned = filePath.split(/[?#]/)[0];
          const m = cleaned.match(/([^/]+)\.svg$/);
          const name = m ? m[1] : null;
          // Diagnostic: log standalone and presence in inlineAssets
          try {
            logger.debug &&
              logger.debug(
                '[FileWatcher] standalone=',
                standalone,
                'inlineHasKeys=',
                Object.keys(inlineAssets).slice(0, 5),
              );
          } catch (_e) { void _e; }
          try {
            logger.debug &&
              logger.debug(
                '[FileWatcher] checking asset',
                name,
                'present=',
                !!(name && inlineAssets && inlineAssets[name]),
              );
          } catch (_e) { void _e; }
          if (name && inlineAssets[name]) {
            logger.debug &&
              logger.debug(
                '[FileWatcher] Short-circuited HEAD for inlined asset ' +
                  name +
                  ' path ' +
                  filePath,
              );
            return Date.now();
          }
        }
  } catch (_e) { void _e; }
      logger.debug && logger.debug('[FileWatcher] Issuing HEAD for', filePath);
      // Try HEAD request to get last-modified header
      const response = await fetch(filePath, {
        method: 'HEAD',
        cache: 'no-cache', // Ensure we don't get cached response
      });

      if (!response.ok) {
        return null;
      }

      const lastModified = response.headers.get('last-modified');
      if (lastModified) {
        return new Date(lastModified).getTime();
      }

      // Fallback: try to get etag or content-length change
      const etag = response.headers.get('etag');
      const _contentLength = response.headers.get('content-length');

      if (etag) {
        // Use etag as a simple change indicator
        return etag.split('').reduce((hash, char) => {
          return (hash << 5) - hash + char.charCodeAt(0);
        }, 0);
      }

      // Last resort: use current time (not ideal but prevents errors)
      return Date.now();
    } catch (_e) {
      void _e;
      return null;
    }
  }

  // Notify callback about file change
  private notifyChange(filePath: string, changeType: 'modified' | 'deleted' | 'created'): void {
    const callback = this.watchers.get(filePath);
    if (callback) {
      try {
        callback(filePath, changeType);
      } catch (_error) {
        void _error;
        try {
          logger.error(`[FileWatcher] Error in change callback for ${filePath}:`, _error);
        } catch (_e) {
          void _e;
        }
      }
    }
  }

  // Watch multiple files
  watchMultiple(filePaths: string[], callback: FileChangeCallback): void {
    filePaths.forEach((filePath) => this.watch(filePath, callback));
  }

  // Stop watching all files
  unwatchAll(): void {
    const filePaths = Array.from(this.watchers.keys());
    filePaths.forEach((filePath) => this.unwatch(filePath));
  }

  // Get list of watched files
  getWatchedFiles(): string[] {
    return Array.from(this.watchers.keys());
  }

  // Set poll interval for all watchers
  setPollInterval(intervalMs: number): void {
    this.pollInterval = Math.max(100, intervalMs); // Minimum 100ms

    // Restart all watchers with new interval
    const filePaths = Array.from(this.watchers.keys());
    const callbacks = new Map(this.watchers);

    this.unwatchAll();

    filePaths.forEach((filePath) => {
      const callback = callbacks.get(filePath);
      if (callback) {
        this.watch(filePath, callback);
      }
    });
  }

  // Toggle one-shot mode. Default is true (check once at watch time).
  // Call setOneShotMode(false) to enable continuous polling behavior.
  setOneShotMode(oneShot: boolean) {
    this.oneShotMode = !!oneShot;

    // If switching from one-shot to continuous, restart watchers
    if (!this.oneShotMode) {
      const filePaths = Array.from(this.watchers.keys());
      filePaths.forEach((fp) => {
        // restart watch to ensure interval is set
        const cb = this.watchers.get(fp);
        if (cb) {
          this.unwatch(fp);
          this.watch(fp, cb);
        }
      });
    } else {
      // If switching to one-shot, clear all intervals
      this.pollIntervals.forEach((id, fp) => {
        clearInterval(id);
        this.pollIntervals.delete(fp);
      });
    }
  }

  // Force check all watched files immediately
  async checkAllFiles(): Promise<void> {
    const filePaths = Array.from(this.watchers.keys());
    await Promise.all(filePaths.map((filePath) => this.checkFile(filePath)));
  }
}

// Global file watcher instance
let globalFileWatcher: FileWatcher | null = null;

export function getFileWatcher(): FileWatcher {
  if (!globalFileWatcher) {
    globalFileWatcher = new FileWatcher();
  }
  return globalFileWatcher;
}

// Convenience function to watch SVG files
export function watchSVGFiles(svgUrls: string[], callback: FileChangeCallback): void {
  getFileWatcher().watchMultiple(svgUrls, callback);
}

// Convenience function to unwatch SVG files
export function unwatchSVGFiles(svgUrls: string[]): void {
  const watcher = getFileWatcher();
  svgUrls.forEach((url) => watcher.unwatch(url));
}

/**
 * Lightweight hotpath performance meter for frame-time attribution
 * Provides begin()/end() instrumentation that no-ops when disabled
 */

interface PerfSample {
  name: string;
  ms: number;
  timestamp: number;
}

interface SubsystemStats {
  name: string;
  totalMs: number;
  count: number;
  avgMs: number;
  p95Ms: number;
  samples: number[];
}

interface PerfSummary {
  frameCount: number;
  totalFrameMs: number;
  avgFrameMs: number;
  p95FrameMs: number;
  subsystems: SubsystemStats[];
}

class HotpathMeter {
  private enabled = false;
  private samples: PerfSample[] = [];
  private activeTimers = new Map<string, number>();
  private maxSamples = 1000; // Rolling buffer size
  private maxFrames = 300; // Max frames for p95 calculations

  constructor() {
    // Auto-enable via query param ?debugPerf=1 or explicit config
    if (typeof window !== 'undefined' && window.location?.search.includes('debugPerf=1')) {
      this.enable();
    }
  }

  enable(): void {
    this.enabled = true;
    console.debug('[perf] hotpath meter enabled');
  }

  disable(): void {
    this.enabled = false;
    this.samples.length = 0;
    this.activeTimers.clear();
  }

  isEnabled(): boolean {
    return this.enabled;
  }

  begin(name: string): void {
    if (!this.enabled) return;
    this.activeTimers.set(name, performance.now());
  }

  end(name: string): void {
    if (!this.enabled) return;

    const startTime = this.activeTimers.get(name);
    if (startTime === undefined) {
      console.warn(`[perf] end() called for '${name}' without matching begin()`);
      return;
    }

    const endTime = performance.now();
    const duration = endTime - startTime;

    this.samples.push({
      name,
      ms: duration,
      timestamp: endTime,
    });

    // Trim samples if over limit
    if (this.samples.length > this.maxSamples) {
      this.samples.shift();
    }

    this.activeTimers.delete(name);
  }

  getSummary(): PerfSummary {
    if (!this.enabled || this.samples.length === 0) {
      return {
        frameCount: 0,
        totalFrameMs: 0,
        avgFrameMs: 0,
        p95FrameMs: 0,
        subsystems: [],
      };
    }

    // Group samples by subsystem
    const subsystemMap = new Map<string, number[]>();

    for (const sample of this.samples) {
      if (!subsystemMap.has(sample.name)) {
        subsystemMap.set(sample.name, []);
      }
      subsystemMap.get(sample.name)!.push(sample.ms);
    }

    // Calculate stats for each subsystem
    const subsystems: SubsystemStats[] = [];
    let totalFrameMs = 0;

    for (const [name, samples] of subsystemMap) {
      const sortedSamples = samples.slice().sort((a, b) => a - b);
      const totalMs = samples.reduce((sum, ms) => sum + ms, 0);
      const avgMs = totalMs / samples.length;
      const p95Index = Math.max(0, Math.floor(sortedSamples.length * 0.95) - 1);
      const p95Ms = sortedSamples[p95Index] || 0;

      subsystems.push({
        name,
        totalMs,
        count: samples.length,
        avgMs: Math.round(avgMs * 100) / 100,
        p95Ms: Math.round(p95Ms * 100) / 100,
        samples: samples.slice(-this.maxFrames), // Keep recent samples for trending
      });

      totalFrameMs += totalMs;
    }

    // Sort subsystems by total time (highest first)
    subsystems.sort((a, b) => b.totalMs - a.totalMs);

    const frameCount = Math.max(...Array.from(subsystemMap.values()).map((s) => s.length));
    const avgFrameMs = frameCount > 0 ? totalFrameMs / frameCount : 0;

    // Calculate p95 frame time (approximation based on sum of p95s)
    const p95FrameMs = subsystems.reduce((sum, s) => sum + s.p95Ms, 0);

    return {
      frameCount,
      totalFrameMs: Math.round(totalFrameMs * 100) / 100,
      avgFrameMs: Math.round(avgFrameMs * 100) / 100,
      p95FrameMs: Math.round(p95FrameMs * 100) / 100,
      subsystems,
    };
  }

  printSummary(): void {
    const summary = this.getSummary();

    if (summary.frameCount === 0) {
      console.log('[perf] No performance data available');
      return;
    }

    console.log(`[perf] Performance Summary (${summary.frameCount} samples)`);
    console.log(
      `Total: ${summary.totalFrameMs}ms | Avg: ${summary.avgFrameMs}ms | P95: ${summary.p95FrameMs}ms`,
    );
    console.log('');
    console.log('Subsystems (ranked by total time):');

    for (const subsystem of summary.subsystems) {
      const percentage =
        summary.totalFrameMs > 0 ? Math.round((subsystem.totalMs / summary.totalFrameMs) * 100) : 0;

      console.log(
        `  ${subsystem.name.padEnd(20)} ${percentage}%`.padEnd(27) +
          `avg: ${subsystem.avgMs}ms  p95: ${subsystem.p95Ms}ms  (${subsystem.count} calls)`,
      );
    }
  }

  clear(): void {
    this.samples.length = 0;
    this.activeTimers.clear();
  }

  // Get recent samples for overlay display
  getRecentSubsystemTimes(windowMs = 1000): Record<string, number> {
    if (!this.enabled) return {};

    const now = performance.now();
    const cutoff = now - windowMs;
    const recentSamples = this.samples.filter((s) => s.timestamp >= cutoff);

    const subsystemTotals: Record<string, number> = {};
    for (const sample of recentSamples) {
      subsystemTotals[sample.name] = (subsystemTotals[sample.name] || 0) + sample.ms;
    }

    return subsystemTotals;
  }
}

// Global instance
export const perf = new HotpathMeter();

// Convenience functions for instrumentation
export function perfBegin(name: string): void {
  perf.begin(name);
}

export function perfEnd(name: string): void {
  perf.end(name);
}

export function perfEnabled(): boolean {
  return perf.isEnabled();
}

// Expose to global scope for console access
if (typeof window !== 'undefined') {
  (window as any).perf = perf;
}

export function enablePerfCollectorIfRequested(): void {
  try {
    const enabled = typeof location !== 'undefined' && location.search.includes('debugPerf=1');
    if (!enabled) {
      return;
    }
    if ((window as any).__perf && typeof (window as any).__perf.addEvent === 'function') {
      try {
        console.debug('[perf] collector already active (init)');
      } catch (_e) {
        void _e;
      }
      return;
    }
    const perf = {
      _frameTimes: [] as number[],
      _events: [] as { name: string; ms: number; t: number }[],
      addEvent(e: { name: string; ms: number }) {
        this._events.push({ name: e.name, ms: e.ms, t: performance.now() });
        if (this._events.length > 2000) this._events.shift();
      },
      startFpsSampling() {
        let last = performance.now();
        const loop = (ts: number) => {
          const dt = ts - last;
          last = ts;
          this._frameTimes.push(dt);
          if (this._frameTimes.length > 600) this._frameTimes.shift();
          requestAnimationFrame(loop);
        };
        requestAnimationFrame(loop);
      },
      getFpsStats() {
        const arr = this._frameTimes.slice();
        if (!arr.length) return { avgFps: 0, p99FrameMs: 0 };
        const avg = arr.reduce((a: number, b: number) => a + b, 0) / arr.length;
        const fps = 1000 / avg;
        const sorted = arr.slice().sort((a: number, b: number) => a - b);
        const idx = Math.max(0, Math.floor(sorted.length * 0.99) - 1);
        return { avgFps: fps, p99FrameMs: sorted[idx] };
      },
      getEvents() {
        return this._events.slice();
      },
    } as any;
    (window as any).__perf = perf;
    perf.startFpsSampling();
    try {
      console.debug('[perf] collector enabled (init)');
    } catch (_e) {
      void _e;
    }
  } catch (_e) {
    void _e;
  }
}
